-- vme snapshot, by vme-content/actions_scripts/createData; loaded by vme-app SqlSnapshotProvider
-- diff 干净依赖稳定排序：items by id ASC, item_tags by (item_id, tag) ASC

CREATE TABLE items (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  author TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  reactions INTEGER NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('text','meme')),
  tag_hash TEXT NOT NULL DEFAULT '',
  url TEXT NOT NULL DEFAULT ''
);
CREATE INDEX idx_items_author ON items(author);
CREATE INDEX idx_items_type ON items(type);
CREATE INDEX idx_items_created ON items(created_at);
CREATE INDEX idx_items_reactions ON items(reactions);

CREATE TABLE item_tags (
  item_id TEXT NOT NULL,
  tag TEXT NOT NULL,
  PRIMARY KEY (item_id, tag)
);
CREATE INDEX idx_item_tags_tag ON item_tags(tag);

BEGIN;
INSERT INTO items VALUES ('I_kwDOHp_P8c5al207','今天是什么日子我自不必多说，作为2k23の第一个疯狂星期四，希望在座各位好自为之，vivo50','今天是什么日子我自不必多说，作为2k23の第一个疯狂星期四，希望在座各位好自为之，vivo50','SleepyAsh0191',1672882997000,0,'text','dd521bafcf40c9ac9ceba3258df363b6bf18829157a9763267a1ab0877f56071','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/145');
INSERT INTO items VALUES ('I_kwDOHp_P8c5aMwlg','阳了','我大抵是病了，横竖都起不来，屋外的咳嗽声此起彼伏，心情复杂的没有来由，黯然吸了一下鼻子，一边是堵的，另一边也是堵的。挣扎着打开手机，看到下好的影片，今日心中却意外地生出了抗拒学习的念头。也罢，大抵是冬天到了。我点上一支烟，狗叫唤了几声，我也跟着咳嗽了几声，不为别的，只是想抒发一下心中的郁结，近来夜里冷的厉害，两床被子面对这寒冷的挑衅，也显得有些许吃力了，或许只有v我50，才能让我感到温暖罢了。','billcoco',1672278684000,0,'text','160d6cf5027d3758f47badf6414c4cb284a3fea6e837e15040fa32b7b227e326','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/144');
