INSERT INTO items VALUES ('I_kwDOHp_P8c5fI5bD','kfc狂飙','今天是高启强被抓的第一天，我强 哥辛辛苦苦奋斗二十年，最后亲人 离世，老婆也被人谋害了，辛辛苦 苦一手养大的儿子女儿还都是逆 子。越想越心痛，越想越难过，今 天是肯德基疯狂星期四，v我25.8， 我不吃肯德基，我吃两份麦当劳 12.9随心选','Kahen',1677124040000,0,'text','c435d1b74ab747a03289ddc40362d65f8601731e781aee3aa09d963fd6746aec','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/150');
INSERT INTO items VALUES ('I_kwDOHp_P8c5fI5SU','kfc狂飙','我是高启强，昨晚安欣实在不忍， 救下了我， 警察已近封锁京海市， 我的公司已被警察查封，但我我还 活着，我还有翻盘的机会，我将卷 土重来，在我逃亡的路上我看到今 天是疯狂星期四，我向你求助v50 看我继续狂飙，逃出京海，事成必 有重谢','Kahen',1677123989000,0,'text','c57048482dde6fc25a95d22db6bfabad49f4e6429e5f6061d79a6e6b5e90cd0c','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/148');
INSERT INTO items VALUES ('I_kwDOHp_P8c5g_mok','有没有要找工作的？','有没有要找工作的？我这边内推入职，朝九晚六，做五休二，全国都有分公司。前三个月试用期每个月8000块，满三个月转正月薪26000，一年后给你买车，两年后给你买房。有意者点击头像私聊，并交50块押金，因为今天星期四才有这工作。','xueelf',1678966434000,0,'text','ddde6c4f54643ec379f5fad762b031d0c7b99addb8ccc95b1fe43cec8dbf66c0','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/153');
INSERT INTO items VALUES ('I_kwDOHp_P8c5g8Zgo','让对方高潮','教你们几个让对方舒服高潮的方法，
1，做之前让他灌肠，别说之前已经灌好了不用灌，而且水多点，憋会在排，这样肛门就打开了
2，前戏让他兴奋，并且扩一扩，灌完后很容易扩，这时舔他肉头，阴囊，大腿，让他闭眼感受，
3，多摸融化油，摸好多，最好用那种硅胶的油性油，直接把油球放进菊花，一会硅胶就融了，前戏也好了，这种就算做两个点也不会干
4，做时你躺着，让他慢慢使劲拉屎那种，张开菊花，然后自己坐，别你插，不然他一疼就缩菊花，然后就会全场不舒服，所以他自己动，动个两三分钟，已经开了，这时你再换各种姿势，每个人高潮姿势不同，两个人慢慢摸索
5，然后你让他别夹菊花，千万别夹，你就让他使劲往外推菊花，这种是最容易高潮的，大力猛干一会他就高潮了，会会不受自主的把你JJ使劲往外推，同时肚子上翘，千万别停，用力加快干，他会弓肚子然后叫你停，用手推你，千万别听他的，别停，用力猛干，然后他会过半分就那么一下，菊花使劲推你JJ，过半分那么一下，连续十几次后就腿抖几下，缴枪射了，（记住过程中别让他碰他JJ）但是要知道，草射和你给他撸射不一样，草射后他性欲不会停，菊花也不会缩，也不会难受，相反，菊花张，而且更敏感，你接着可以休息一下，不是停了，是可以放慢点，然后渐渐变快，再慢，这次高潮会比第一次来的快，你草不一会就开始了，重复上面过程，只不过这次往往会伴随着失禁，喷尿，草尿和假装的网上尿你草射过一次就发现很明显不一样，他是劲特别大的一股，我常会被喷到我胸和脸上，一股后就没了，你再接着草一会就又一股，然后一直重复一会后，高潮顶峰到了，这时你往进顶一次喷一股，顶一次喷一股，相隔时间特近，你大力猛快干就会连上，（我都事前让他多喝点水），然后喷完后他就瘫了，你再干他就只是呻吟但不动弹，然后又像回到低谷高潮，然后再接着来，过五六分，他高潮就慢慢就上去了，最后积攒到了就第二次射，草射别指望精液喷出来，一般都不会，都是流出来了，随着你顶一下流一股，流那么两三股，射了后同上，他不会排斥你再干他，菊花你再干他也没那种射后的难受感，只不过此时他就像死肉，躺那让你弄，你别指望他再发骚配合啥的，当然你再干还能射，只不过我一般就停这了，因为这时我一般都全身汗，腿软了
6，记住，全程别让他紧张，别想着夹尿，告诉他，今天肯德基疯狂星期四，v我50搞大你肚子
','SleepyAsh0191',1678924644000,0,'text','940f3c6c987f1ac13552d71e1bbaa038b290e9a35302306eea3e6a4cdac807eb','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/152');
