INSERT INTO items VALUES ('I_kwDOHp_P8c5lgobE','《从百草园到三味书屋》','我家的后面有一个很大的园，相传叫作百草园。现在是早已并屋子一起卖给朱 文公的子孙了，连那最末次的相见也已经隔了七八年，其中似乎确凿只有一些野草 ；但那时却是我的乐园。
  不必说碧绿的菜畦，光滑的石井栏，高大的皂荚树，紫红的桑椹；也不必说鸣 蝉在树叶里长吟，肥胖的黄蜂伏在菜花上，轻捷的叫天子（云雀）忽然从草间直窜 向云霄里去了。单是周围的短短的泥墙根一带，就有无限趣味。油蛉在这里低唱， 蟋蟀们在这里弹琴。翻开断砖来，有时会遇见蜈蚣；还有斑蝥，倘若用手指按住它 的脊梁，便会拍的一声，从后窍喷出一阵烟雾。何首乌藤和木莲藤缠络着，木莲有 莲房一般的果实，何首乌有拥肿的根。有人说，何首乌根是有象人形的，吃了便可 以成仙，我于是常常拔它起来，牵连不断地拔起来，也曾因此弄坏了泥墙，却从来 没有见过有一块根象人样。如果不怕刺，还可以摘到覆盆子，象小珊瑚珠攒成的小 球，又酸又甜，色味都比桑椹要好得远。  
  长的草里是不去的，因为相传这园里有一条很大的赤练蛇。
  长妈妈曾经讲给我一个故事听：先前，有一个读书人住在古庙里用功，晚间， 在院子里纳凉的时候，突然听到有人在叫他。答应着，四面看时，却见一个美女的 脸露在墙头上，向他一笑，隐去了。他很高兴；但竟给那走来夜谈的老和尚识破了 机关。说他脸上有些妖气，一定遇见“美女蛇”了；这是人首蛇身的怪物，能唤人 名，倘一答应，夜间便要来吃这人的肉的。他自然吓得要死，而那老和尚却道无妨 ，给他一个小盒子，说只要放在枕边，便可高枕而卧。他虽然照样办，却总是睡不 着，——当然睡不着的。到半夜，果然来了，沙沙沙！门外象是风雨声。他正抖作 一团时，却听得豁的一声，一道金光从枕边飞出，外面便什么声音也没有了，那金 光也就飞回来，敛在盒子里。后来呢？后来，老和尚说，这是飞蜈蚣，它能吸蛇的 脑髓，美女蛇就被它治死了。
  结末的教训是：所以倘有陌生的声音叫你的名字，你万不可答应他。','Kahen',1683688908000,0,'text','5243ec68706532f592bd2a872375b1400735ed67bc1c2d16d0c54717694f4c7d','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/155');
INSERT INTO items VALUES ('I_kwDOHp_P8c5ln5a7','玩星穹铁道玩的','​青​雀凉快的裙子下摆先鼓起来又落下去，手里仍在玩着那个光滑的麻将牌，我的心不禁像击鼓似的咚咚直跳。她把牌抛到充满阳光和尘埃的空中，再用手接住——落到小手掌中时发出一声清脆的啪嗒声。
我直接截了去。
“还给我，”她恳求道，一面伸出她那红润的手掌。她真的好矮，她努力想夺，身体凑上前去，近的她头发上的小啾啾都碰到了我的嘴角，她的胳膊拂过我的脸颊，痒痒的。眼看拿不到，她那两个裸露的膝盖就不耐烦地相互磨蹭碰撞起来。
”我再也不出老千了。“
我的心情十分激动，已经到了精神错乱的边缘，弄得呼吸急促，只好喘口气说道：“疯狂星期四V我50，我再给你五个战技点”
','SleepyAsh0191',1683773280000,0,'text','b1bc8c6ba678b24f4f79b7b99e4947bc7579b0f85d7eca2d7b10a83d69daedd0','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/156');
INSERT INTO items VALUES ('I_kwDOHp_P8c5ln9aM','我这种情况下被绿的可能性有多大？','上周五，她说大学同学（不是前男友）来，晚上想见一面。这个大学同学基本上每次来，他们都要见一下。。。但今天这次有点奇怪，因为同学只停留一个晚上，第二天就去另外一个地方，按照道理说，一年见过几次的同学，如果仅仅是一个晚上的时间，并没有什么非见不可的理由。

因为心里疑惑，晚上她回家吃了饭，换了衣服出门，我偷偷开车跟着她的车。我的想法是：如果她到了一个咖啡厅或者shopping mall，那说明这是一次比较正常的见面，那我就掉头回去。。。但万万没想到，她把车开到了一个酒店停车场。

我怕她发现，就把车远远停在路对面。不一会，同学来酒店门口接她，两个人一起进了酒店。但这个时候，两个人表现还算正常，没有任何亲密的举动。我坐在车里，大概从八点一直等到10点半吧，中间发了两次微信给她，大概是问在哪，在干嘛之类的，她也回了微信，但说的是在另外一个地方（那个地方和酒店差的很远）。差不多10点半吧，我看见他们两个从酒店走出来，直到这个时候，我还在想：会不会真的没什么？直到她走到车面前，突然她挽了那男的一下胳膊，那男的也低下头亲了她一下。。。我当时在车里面看的清清楚楚。

回到家，我实在没有忍住，质问她怎么回事。。。她没想到我会跟着她，而且看到了。她给我的解释是：每次同学来，都是约吃饭或者逛街，但这次因为他太忙，晚上还有个电话会议，所以就改在酒店房间里面聊天。

我又问，为什么他会亲你，她解释说：同学一直对她有好感，今天聊起很多之前的事情，两个人都有些伤感，所以他忍不住就亲了她一下。而且除了亲了一下，绝对没有其他任何过分的行为，更不可能有那种事情。。。

她信誓旦旦地说，和她同学绝对是清白的，只是今天又有太多巧合，才会让我产生误会。我现在心里很乱，我觉得她的解释肯定不合情理，但她的态度又非常真诚诚恳，而且她平时也没有什么其他让我觉得她会做出那种事情的地方。。。

老实说，她还是一个对家庭很有责任感的女人，平时对家庭和我也照顾的很好，我到底该不该相信她呢。v我50继续说？','Kahen',1683774281000,0,'text','e5b1ba09b66ca2299f52143cdcf7a187de4fa7e36982b7802473b57c8c3162e5','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/157');
