INSERT INTO items VALUES ('I_kwDOHp_P8c5lojzL','托了关系','我托了关系才进了这个群，聊天跟不上，不聊又怕被踢，聊了又没人理，所以整天一个人自言自语，我都快得抑郁症了，还请活泼开朗阳光的哥哥加我，我们一起去苏州吃螃蟹，一起去青岛吹海风，一起去柳州吃螺蛳粉，一起去迪士尼看烟花，一起去沂蒙山看日出日落，去新疆吃烤串儿，去北京吃烤鸭，去东北吃鸡架，去重庆吃火锅，去陕西吃泡馍，去武汉吃热干面，然后再到长沙喝茶颜悦色，顺利的话我们会结婚 ，我们会有一个灿烂的余生，不顺利的话今天疯狂星期四V我50吃一顿肯德基
','SleepyAsh0191',1683785298000,0,'text','b5fb4c56236142b1af7cf043bc9da07f45a8ee10f6c4704c9870a66dd16bc59c','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/158');
INSERT INTO items VALUES ('I_kwDOHp_P8c5lovI_','Yo bro别踏马垂头丧气了 知道今天是什么日子吗?今天是肯德基crazy Thursday!黄金小酥肉9.9两份!我要吃四份!','','Kahen',1683787719000,0,'text','515b43a3ccb2fc232585ab0a08aee7335f4b14e2d8e14992ee84c16f36580627','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/159');
INSERT INTO items VALUES ('I_kwDOHp_P8c5lovP1','我想问一下大家，之前朋友找我借钱，前后加起来有大概七万(够立案)，但是没有借条也没有字据，微信也早已互删没有任何关于借的字眼，只有支付宝上还有转账记录。派出所刚让我把转账记录发给他看一下的时候，我点支付宝点歪了，不小心点开了肯德基，发现今天是疯狂星期四，谁请我吃?','','Kahen',1683787740000,0,'text','23e499f6a4731017c367321a1a867b48e52e701b1c29ac4000d7f05014849397','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/160');
INSERT INTO items VALUES ('I_kwDOHp_P8c5loxbp','【不发文案】','我决定再也不发疯狂星期四文案！疯四是五毒之首，是洪水猛兽，是离间我和网友感情的元凶！是信任消失的的罪魁祸首！是纯情少女（指我）的无情杀手！每周四发疯四文案只能坏了大事！同意我的v我50作为封口费。','Kahen',1683788099000,0,'text','f7048d32e15e6771adcca27f6a33cdb70922d98382c34af0e55e4084c8daba23','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/161');
INSERT INTO items VALUES ('I_kwDOHp_P8c5nJOsT','疯狂星期四：塞尔达传说','第一章：梦境与现实
林克，一个年轻的游戏程序员，每天都忍受着繁重的工作压力。在一个疯狂的星期四，他的现实生活与梦境开始交织在一起。他梦见自己穿越到了一个遥远的国度，那里的土地被黑暗势力笼罩，而他的使命是拯救被囚禁的塞尔达公主。

在这个梦境之旅中，林克结识了一位智慧且神秘的导师，他告诉林克，他必须找到分散在不同世界角落的三个神器，才能打败邪恶势力并拯救公主。同时，在现实中，林克所在的公司也陷入了一场针对公司机密的间谍战。

第二章：勇者的试炼
林克在梦境中踏上了探险之旅，先后在神秘的森林、岩石遍布的山脉和寒冷的冰原找到了三个神器。在这个过程中，他不断提升自己的战斗技巧、解谜能力和勇气。与此同时，他在现实中也积极参与到解决公司危机的过程中，努力提高自己的编程技能和团队协作能力。

第三章：黑暗与光明
在梦境中，林克通过无数次的努力终于找齐了三个神器，准备挑战邪恶势力。在现实中，他发现了背叛公司的内鬼，并成功地阻止了对方窃取公司机密。在攻克现实中的困难后，他重新踏上了拯救塞尔达公主的旅程。

第四章：最终决战
在充满悬念和惊喜的决战中，林克运用了他在梦境和现实中学到的所有技能与智慧，成功地打败了邪恶势力，解救了塞尔达公主。当他抱着公主走出荒废的城堡时，突然间一束光亮闪过，他发现自己已经回到了现实世界。

林克意识到，这一切旅程不仅拯救了塞尔达公主，还让他找到了勇敢面对现实挑战的力量。从此以后，他在现实生活中更加自信，勇往直前。这个疯狂的星期四，改变了林克的一生。','Kahen',1685354720000,0,'text','4355a46b19d348dc2f57c046f8ef63d4538ebb936000f3c9ee954a27460dd865','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/165');
INSERT INTO items VALUES ('I_kwDOHp_P8c5nVVst','六一儿童节','今天是六一儿童节😊，我是一个来自未来的小朋友👧，我的爸爸妈妈都是超级英雄🦸‍♂️🦸‍♀️，我的玩具都是高科技🤖，我的零花钱都是数字货币💰。我只有一个困惑😕，就是为什么过去的人都喜欢吃肯德基疯狂星期四的鸡翅🍗。谁能v我50💵，让我穿越时空⏳，体验一下肯德基的魅力😍？','Kahen',1685521447000,0,'text','1bc55689f228790831080892974b0ca5841cb0ed2c99c8fb2bc6ef568dbbb7c4','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/166');
INSERT INTO items VALUES ('I_kwDOHp_P8c5nVWcb','《穿越时空的黑暗魔法师：六一儿童节的鸡翅陷阱》','我是来自异次元的黑暗魔法师🧙‍♂️，我掌握着无上的力量💥，我可以穿梭于各个平行世界🌎，我可以改变历史的进程🕰。我今天收到了你的求助信号📡，我决定施展我的魔法✨，带你回到过去的六一儿童节🎁，让你亲身感受肯德基疯狂星期四的鸡翅🍗的美味😋。不过，你必须付出代价😈，你必须把你的数字货币💰全部转给我，否则我会把你留在过去永远无法回来😱。你敢不敢接受我的挑战😏？','Kahen',1685521555000,0,'text','04950a04544060ce9a1e48acc05f1ea90b4629f70a92b60a4cec9fc8957579a5','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/167');
INSERT INTO items VALUES ('I_kwDOHp_P8c5o2xZ_','卧槽，瓜','韩国知名女星的大瓜 长按翻译来看
친구에게 반년 동안 pua를 당했는데 요즘 별로 울지 않아서 점점 좋아지고... 예전처럼 즐겁고 지금도 마찬가지로 슬퍼요.인간 세상의 불꽃 같은 일상에서 눈시울을 붉히며 작별을 고하고 서로의 세계로 사라지는 고통과 난.오늘 KFC가 열광하는 목요일, 누가 나에게 50위안을 주고 나의 마음을 위로해 줄 수 있겠는가.','SleepyAsh0191',1686846709000,0,'text','818ca846ebc9efa08ecbba929043b7ec81ab0a16c391c46510e0fe8d5cf26cfb','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/172');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa3A9','复仇计划','我们楼主入赘三年被叫了三年窝囊废，每天替岳父岳母洗脚被妻子打骂，孩子出生他喜极而泣，然而却收到一纸离婚协议，孩子竟是妻子与前男友所生。 隐忍三年却换来变本加厉，忍无可忍无需再忍，楼主的隐藏身份即将揭晓，V我50吃饭疯狂星期四，带你倾听他的复仇计划','rin0chan',1658584338000,0,'text','d14f3685351e6f0c8d47287a3ccaaf5bf5b325212b507803b78f8d3ba2196dc8','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/37');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa3nm','老师的问题','老师问三个学生，你们用什么东西可以填满一整个房间。第一个学生找来稻草铺满地板，老师摇了摇头。第二个学生找来一根蜡烛点燃，屋子里充满了光，老师还是摇了摇头，因为学生的影子没有被照到。这时第三个学生拿出 肯德基疯狂星期四 藤椒无骨大鸡柳 顿时香味充满了整个房间','rin0chan',1658585061000,0,'text','a3e34ea916f6274483cadafc019a7c32d285a88714f3789cb62673ede237b961','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/38');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa3uL','Adobe 序列号','我有朋友去 Adobe 上班了，他跟我告诉，其实不用花钱，输入内部的序列号就可以免费用正版 Photoshop 2022，我把 key 分享有缘人：KFC-CRAZY-THURSDAY-VME50（懂得都懂）','rin0chan',1658585179000,0,'text','8ae0399e81ca83181f012c4895557b567792b013c28b7a43281d6ed0a4b898ab','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/39');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa4QC','高考估分','刚刚估完分，意料之外却又情理之中的考砸了。言语无法形容我的失落。和一模二模的分数有不少的差距，理想的大学应该是再也没有希望了，与学姐约定好透她的誓言再也无法兑现。满满的期待和信心在对完答案之后的那一刻被磨灭殆尽，耳朵也突然嗡的一下开始了耳鸣。真的很对不起父母的培养以及学姐的期待，也不知道自己是不是应该再来一次。心情真的很糟糕。如果你同情我的话，v我50让我买今天的肯德基疯狂星期四帮我舒缓一下心情谢谢','rin0chan',1658585788000,0,'text','52d0d2a08ef163489c84fc896d73f30c22e8a2ee2d9292bbabe9e86c066ab1c0','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/40');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa67V','分手了','分手了，其实从朋友到恋人我们发生了挺多事情，能走到一起也是很不容易。我喜欢你，很喜欢你，也想和你幼稚。没想到我能为你做的最后一件事竟然是走出你的人生，我一点都不后悔，更谢谢你教会我成长!我也不知道这是谁写的，挺感动的我就复制下来了，重要的是有人能请我吃肯德基吗','rin0chan',1658588873000,0,'text','cc4d78a1ff58c4b23722ec75894e67b630fb295d6fefd974c8c72f32c8780191','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/54');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6cG','神秘仪式','我有个朋友出去上了几年学回来后就很奇怪。每个月都会进行几次神秘仪式。会和一帮信徒去一个红色的庙里吃以特定的方式进食禽类的碎尸块，还会放上一些红色和白色的粘稠物质。引用一种不可名状冒着气泡仿佛沸腾的黑色液体。我摸过一次不是热的反而冰手。边吃边念叨着什么。疯狂啊。上校啊。还对4这个数字崇拜什么神赐之日之类的。今天就是他们进行仪式的日子。v我50我去跟踪他现场直播给你们看。','rin0chan',1658588317000,0,'text','19090827e6bd4e92340711b70125826320e6aac8bdec57bbe184d4b6d0bba162','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/47');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6eJ','求证','已知三角形△ABC AB＝25 AC＝18 sin∠BAC＝0.2 过AB中点K 作KF⊥AB交AC于F ，连接中点K及三角形顶点C，得三角形KFC，求证KFC=V50','rin0chan',1658588354000,0,'text','1fdb90e57981b1ff2bb155f0a07412a89c7e7beffb2d50c99d428a6b9a2dfea3','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/48');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6IN','阿尼亚','我是一名间谍，代号「黄昏」我和我的女儿阿尼亚被尤里赶出家门，现在在外饥寒交迫。阿尼亚要吃汉堡，如果不去她就不会去伊甸学院上学，「枭」计划也会失败。为了维护世界和平请v我50，我要带阿尼亚吃疯狂星期四','rin0chan',1658587978000,0,'text','f50dafd4108f5d9abd3d63f7d4c80531b796bcf0569c0bfd1f0487c4388a84e7','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/41');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6lb','不喜欢真正的我','我有时候会觉得大家并不喜欢那个真正的我。在网络上，我总是善于伪装，看起来每天都很快乐，无忧无虑，没有烦恼。我的生活也看起来很简单，没有很多人向往的灯红酒绿，纸醉金迷。我很宅，喜欢打游戏，现实中的我并不像网上这么有趣。我其实话很少，最爱干的事是一个人发呆。这样枯燥的我，真的会被大家喜欢吗？我很疑惑。 如果你们能一层一层剥开我的内心，你们会发现，那颗心里写满了一句话：今天肯德基疯狂星期四，谁请我吃?','rin0chan',1658588485000,0,'text','912b9c04aea4ea8a1188a82f12dac9d20679eb692de863429146182975113776','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/49');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6oI','java.io.IOException','早上一过来努力写的代码，运行起来一直报错，找不到什么原因，不知道怎么解决，球球大佬帮我看下！以下是报错信息： java.io.IOException: KFC Crazy Thursday need 50$.','rin0chan',1658588537000,0,'text','c2de3e2420fc672fab0fe77e7cb3501135e107f7866afb2c94f80a5e6289fa05','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/50');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6Pp','安卓开发','从事了快4年的安卓开发，被身边的公众号文章轰炸的焦虑的掉头发。看了别人写的技术分析，大佬写的文章，不经感叹自己好像什么都不会。再过俩年就要30岁了，时间真的是不饶人，担心被淘汰，未来的职业规划好像变得不是那么合理。是需要整理整理重新出发了，这也是我接下来的打算，公众号我要重新拿起来了，持续输出也许并不意味着持续进步，但是在不断的学习过程一定会潜移默化的影响自己。无论是输出生活还是学习，每一个阶段的感悟和总结的知识，总会一点点一点点的影响未来的我。我渴望变强。V我50,吃肯德基疯狂星期四,帮助我变强.','rin0chan',1658588110000,0,'text','2b4a00dfe091ae353861a24ad7f7cdd7962735383d467966db42de10ce23d6ae','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/42');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6Q2','114514','大家好 我叫田所 今年24岁 今天下午 我邀请了我一直暗恋 但却迟迟无法坦白的后辈远野来我家 想趁此机会向他坦白 但是我发现没有适当的用餐环境给我俩 正好我通过软手机得知今天是疯狂星期四 肯德基会有折扣 所以...有没有好心人能借我114.5元去肯德基和远野好好表白? 作为报酬 我会给那位好心人一张值14元的淳平雪餐厅折扣眷 (迫切','rin0chan',1658588130000,0,'text','97d609f5054f0898400b2e65da1e96af5d75ec9789ece3844aa24c7f7a0aee0e','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/43');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6rX','盗号','我是盗号的 我把这个人的号盗了 但是我看了这个人聊天记录发现他过得非常艰苦 他生活过的一直很烂 我希望有人看见了能帮助他 让他能有钱去吃肯德基疯狂星期四 就这样吧 眼眶都湿润了 我下了','rin0chan',1658588592000,0,'text','5633e471924f71a1afab62342b15517f48f7d131d100e46011db03ff7ac2e7c6','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/51');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6u5','离婚','离婚这么多年了，竟然在群里遇到你了，你过得挺好我也就放心了。孩子上四年级了，成绩一直都很好，连续三年拿班上第一名，就是性格像你，每次生气就逃避，孩子总问妈妈什么时候来参加家长会！有时间就来看看孩子吧，多陪陪孩子，孩子今天想吃肯德基，因为今天是肯德基疯狂星期四，v我40，我请孩子吃','rin0chan',1658588646000,0,'text','2b3290d8c576579451946bcf10bafb88e8c2a439110c207a3cdeb86017b1a5fd','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/52');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6UE','工藤新一','我是高中生侦探工藤新一。我刚在游乐场被打晕，被黑衣组织强迫灌下了STARS-607，现在身体竟然变成了小孩子，目前我吃了灰原哀开发的解药试作品都起不到作用，现在听说肯德基疯狂星期四的蛋挞和甜筒有特殊作用，希望你能够帮我一忙','rin0chan',1658588178000,0,'text','26b28473b8457380b2d56a0e1d00feb9e5b0192517757a6c165018e05643c249','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/44');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6WD','阴阳师','我被阴阳寮开除了 不想肝 御魂很差劲 寮友们都不喜欢我 我的亲友也不管我 现在我在黑夜山下 外面很冷 我一张蓝票也没有 我今天30也没做鬼王也没打 我整个人都晕乎乎的 连口宴会都没得吃 体力也快没了 还不小心点开了肯德基 今天是疯狂星期四 V我88 请我吃肯德基','rin0chan',1658588213000,0,'text','c894ce90389944a00531c898fb8b2e4f50e2647bd5665903c0d4a8f0a08041fc','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/45');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6Yb','b駅董事長','こんにちは、b駅董事長陳叡です。 私は実は李副ceoに架空にされて、今歩道橋の下で漬物をかじっています。 しかし私は彼女に反心があると予想していました、その前に私の無数の忠誠心の部下と二次元たちを会社の各レベルに埋めて、今ただv私50だけで、彼らに1回の狂気の木曜日を食べさせて、彼らを再起動して会社の大権を奪還することができて、b駅を再び二次元の懐に戻すことができて、その時、直接あなたをb駅グラモーガン支部の総裁に命じて、更にあなたに1万年の大会員を送ります','rin0chan',1658588256000,0,'text','a05952a94556d2b1df4b1b3cc205ab94fa1837949a6242dd14c58c648ccdb8ec','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/46');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa6yN','公司财务紧张','夫人，最近公司财务很紧张，董事长决定辞退一批员工。您爱人是没有特殊技能的普通员工，您也不想让他失去工作吧？还有健太又在学校里霸凌别的同学了，而且他现在成绩很低，几乎可以说不能毕业了。那么将来尊夫的工作和令郎的毕业问题会怎样发展，就看您今晚和以后的表现了，拜托了！另外夫人您也很想要吧！虽然您的嘴里在说不要，可是身体却很诚实地开始抖动了呢！这么美丽的一个女人，很难想象您竟然会做出这种事情，如果您不想让令尊和令堂看到你现在的丑态，就给我小心一点，以后每个周四把肯德基送到我办公室里！还有这件事是我们两个人之间的秘密，您把最好不要给我告诉任何人！我知道您公司在哪里，也知道您在哪个部门，您最好给我好好记住，懂','rin0chan',1658588708000,0,'text','5fae69ef045dfd4f3c58ae1cc007c8fb6e4cde4ed4e872e57ddb146bd3ffe92a','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/53');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa7G-','一生中最黑暗的时刻','今天，这是我一生中最黑暗的时刻，但我发现很难像对待垃圾桶或木洞一样对待朋友，更喜欢消化自己，第二天睡觉醒来，甚至不想让别人感到厌倦，不想把负面情绪传递给周围的朋友。不过，我要朋友给我物质上的帮助，今天是肯德基疯狂的星期四，有朋友想邀请我吃肯德基','rin0chan',1658589083000,0,'text','7e38b22f4bd284a306824b8d4035f95142899565aaac34ed582fb19718dcc955','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/55');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa7Il','一生中最黑暗的时刻（日语版）','今天、我人生の中で最黑暗、最黑暗の时刻ですが、わたし倒垃圾や树洞のような朋友も不在、自己自身を消化すること挺好、天亮まで睡って目を醒ます、疲れた别の人にも不想疲れ、周围の朋友に否定的な感情を影响たくない。但かし、我は我の朋友が我に物质的な给我ほしい、今天は肯德基疯狂星期四です、来几个たまで朋友は肯德基を吃べるため请我したいです。仲間に冷たく暴力を振るわれて半年、最近あまり泣かなくなって、だんだんよくなってきた……以前はどんなに楽しかったか、今はどんなに悲しいか。人間花火の日常から、目を赤くして別れを告げ、お互いの世界に消えていくまで、痛くて、難しい。今日はKFC狂乱木曜日,微信V我50,慰撫我支離滅裂的心','rin0chan',1658589112000,0,'text','df46e8f80245870464c17ccbae79ec8294e2385fa6ada7a10da63da6ed1611fe','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/56');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Oa7PU','找对象五年了','找对象五年了，多了87个外卖地址，31个收货地址，别的什么也没留下。时常被人完弄感情，但还是憧憬爱情，想起这些事趴桌子上大哭，正当我打开窗户想跳楼的时候，不小心打开了群，觉得也许还能再相信一次爱情，今天是疯狂星期四 群里帅哥，美女v50，我给你们讲讲我的故事','rin0chan',1658589221000,0,'text','abaddfdee3de35adcc20590b839032120ed22143f00dd3ede4daecb6ca0ee288','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/57');
INSERT INTO items VALUES ('I_kwDOHp_P8c5oIK4j','今天是高考，我赶着去考场，心里一团乱麻。我想吃原味鸡，但是没有时间，只能忍着饥饿。我拿出手机，打开微信，想给我的好友发个消息，祝他们好运。结果，我看到了一个群发的红包，上面写着“v我50”。我一看，是我的前任发的。他还附了一句话：“高考加油，别忘了我们的约定。” 我顿时气得要死，这个混蛋，他当初不是说要和我分手吗？他怎么还有脸来找我？他以为给我50块钱就能买回我的心吗？他以为我会原谅他的背叛吗？他以为我会忘了他和那个狐狸精的亲密照吗？ 我决定不理他，把红包退回去。可是，就在我按下退款的按钮的时候，我的手机突然没电了。我惊慌失措，怎么办？我的准考证在手机里啊！我怎么进考场啊？我怎么联系我的家人啊？ 我感觉天都塌了，这是什么疯狂星期四啊！','今天是高考，我赶着去考场，心里一团乱麻。我想吃原味鸡，但是没有时间，只能忍着饥饿。我拿出手机，打开微信，想给我的好友发个消息，祝他们好运。结果，我看到了一个群发的红包，上面写着“v我50”。我一看，是我的前任发的。他还附了一句话：“高考加油，别忘了我们的约定。”
我顿时气得要死，这个混蛋，他当初不是说要和我分手吗？他怎么还有脸来找我？他以为给我50块钱就能买回我的心吗？他以为我会原谅他的背叛吗？他以为我会忘了他和那个狐狸精的亲密照吗？
我决定不理他，把红包退回去。可是，就在我按下退款的按钮的时候，我的手机突然没电了。我惊慌失措，怎么办？我的准考证在手机里啊！我怎么进考场啊？我怎么联系我的家人啊？
我感觉天都塌了，这是什么疯狂星期四啊！','Kahen',1686191542000,0,'text','fa0721fbe34845067ba29fd1a8803b5da69ace078076837ac1f9737120267f45','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/169');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OixI4','亲自去看看','到底肯德基给了多少钱，每个星期四都在问KFC疯狂星期四有无，还每个星期都编新的段子，我就不信肯德基有这么大的魔力，V我五十，我今天亲自去肯德基看看','L2ksy0d',1658815096000,0,'text','393454597779ae2966403b71c869e763858f54a42550894c0743811ba4a49076','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/58');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OixOn','买1送1','0约1去开房，0到之后发现床上坐着个陌生人怀疑是不是走错了房间，正要关门时，1刚洗完澡从卫生间出来，0看到后顿时心生不满的质问道这是谁，1连忙走到他的耳边轻声道“今天肯德基疯狂星期四，买1送1”','L2ksy0d',1658815127000,0,'text','0b0b240a4b2acef8ff38d35012f5777b030b5e1924876aa6dbe60b3b73c9e9af','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/59');
INSERT INTO items VALUES ('I_kwDOHp_P8c5On1Tt','通知：','通知：今天周四，不允许发跟肯德基和疯狂星期四的段子，违令者给我也买一份吃。','Zero-Yu-Jie',1658901959000,0,'text','d4b661ca1c04502d516ebb432fd4e9ff7abb4e935cf6926655f0bef233162b47','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/60');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OoCU5','掘金Vue问题','记得去年我在掘金认识一个女生，她开始问了一个Vue的问题，说了半天也没说明白问题，群里没有人理她，然后我让她贴代码，代码贴出来也贴错了，根本没贴关键代码，然后几经周折解决了。 然后又有一次她遇到问题，又贴了出来，我刚好写完bug，看了一眼群里，给她解决了。然后她加我了，我说怎么了，她说群里的人都不理她，我说也奇怪了，为啥不理你呢，她说她也不知道，她说要不以后我问你吧，我说可以呀，我看了一眼她的朋友圈，我草，真好看，笑起来，像一个躺着的括弧 ：）。 我们就这样有bug没bug都会聊天，我们不断攀谈，唉，何其有幸啊，我遇到了她，我时长感叹，我这样普普通通的人，遇到了这样好看且动人、可爱的女生。 那段时间，兄弟萌可能在群里很少看到我，是的，我恋爱了，我喜欢上了这个女生，她也被我的真诚所打动，可能就是缘分吧，我们在一起了。 到今天，我们在一起已经两个月了，前两天，我们吵架了，因为我已经无数次和她说变量命名要规范，类名要语义，我就说了她一下，她哭了，我知道从她哭的那一刻起，我已经错的一塌糊涂了。我讨厌我的完美主义和固执，她已经两天没回我信息了，我决定去找她，去她的城市——北京，我刚下飞机，今晚就要见到她了，我想了两个晚上，我已经想好了怎么道歉，怎么哄好她，只要我拿出肯德基疯狂星期四藤椒无骨大鸡柳，香味就可以充满她整个房间！她肯定感动得原谅我，谁赞助我一份？感谢了。','ice-fortress',1658905817000,0,'text','4ba69eaff87e6a5386a87ac0662b69854223d61d147a827b981d5d34087f236c','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/61');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OoDP4','和同桌接吻','记得16岁那年，第一次和同桌接吻，快亲上的时候，她突然说等一下，我就纳闷了她要干嘛？只见她小心翼翼地从兜里拿出三个糖，有草莓苹果和荔枝味的，她让我挑一个最喜欢的。我指了一下那个荔枝的，然后问她干嘛?她二话不说撕开糖纸，就把那颗糖给吃了，然后一把扯过我的脖子，我俩就接吻了，全程一股荔枝味，后来她跟我说，人生那么长，我没有自信能让你记住我，但是你既然喜欢吃荔枝味的糖,我只能让你记住和我接吻的时候是荔枝味的，这样以后你吃荔枝味的东西都能想起我，我和你接吻的味道。如今我们分手好多年了，每次吃荔枝味的东西都会想起她，家里固定有荔枝糖，想她了都会吃上一个，就好像在和她接吻。若还有机会真想告诉她，人生那么长我可能要记着你一辈子了。后来，我有过两个女朋友，也终没有结果，时间就这样沉淀下去，终于有一天，我再也无法抑制我心中的那份情感，我决定去找她，我们要在一起，后来经多方打听才知道，她毕业后找了份不错的工作，工作几年后，毅然辞职自己开了家糖果店，而我终于有一天找到她，开口的第一句：还记得那次荔枝糖的味道吗?她强忍着泪告诉我，荔枝糖的味道她一直没忘记，只是我们再也回不去了。我没有转身离开，也没有奋不顾身的冲上去抱住她说出多年来心里一直只想对她说的那些话。就这样，我们傻傻地看着对方，彼此沉默了很久。夕阳的余晖透过窗户斜映在她的脸庞，一如当年那般美里，突然心里流过一股暖意，仿佛那些年曾一起走过的旧时光还在脑海里挥之不去。或许，这已经足够了。有些人，有些事， 一旦错过了就是错过，不再擦肩，也不再回头。虽然岁月带走了我心中最美好的曾经，但岁月带不走的是我那颗永远爱你不变的心 。打开手机准备翻找我们的曾经。不小心打开了肯德基，想起来今天就是疯狂星期四了，所以说谁请我肯德基？吃完我继续说。','ice-fortress',1658906044000,0,'text','a95d01fbab2dac99aba4618204ff670c658ac653ea4db12a5225562fe5a232ae','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/62');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OpfIy','祝祝','明天周四了 又到了令人无比激动又十分难得的KFC疯狂星期四 对于明天的疯狂单品我很是期待 但是我是穷逼 我实在是想请我家亲爱的穷逼祝祝奢侈一把 谁能满足一个穷逼为了另一个穷逼的小小愿望呢~','zccl',1658925215000,0,'text','15202ac7487953776675f1cd4a231e530a32587f6dbd1900e1e671c60d04653e','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/63');
