INSERT INTO items VALUES ('I_kwDOHp_P8c5Oshhg','复仇计划',' 昨天公司新来一位女同事今天她找我聊天

她说她是她爸妈捡来的

现在19岁，不是亲生的，她自己也知道。

她哥今年27了，读研读博，所以现在还没谈女朋友，她妈突然就跟她说，等她毕业了，她哥要还没有对象她就跟她哥结婚吧。她当时还在看书听到这话吓得我魂都丢了，果断说不行，她妈就说先别急，听她讲完。

她要和她哥结婚了，不用担心她哥对她不好，第ニ她哥哥也不会有婆媳矛盾，第三也不会因为任何原因离开她离开家。

第四她不用养双方父母，将来爸妈生病了她们可以一起照顾，第五知根知底她哥哥还没谈过对象是干净的。

她讲完她就沉默了，确实除了不相爱以外全是利没有弊，她找不出任何驳的理由，本来想说她们没有那种感情只有亲情，她妈后来就说她以后也不一定就能遇到爱她爱的死去活来的人，大家相亲结婚不就是奔着凑合着过的念头才在一起的吗？

她说决定复仇，但是肚子太饿，刚好今天是肯德基疯狂星期四， v 我50我给她肯德基吃，到时候我们一起听她的复仇计划','ice-fortress',1658973598000,0,'text','21d49b85a8879ea1d2d1ba824fd32b68861c1edf256d51aeeb94b15ddba098f3','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/66');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OshlT','求姻缘','7月求姻缘应该去哪个寺？
A、浙江省杭州灵隐寺
B、广东省深圳弘法寺
C、江苏省江市甘露寺
D、肯德基疯狂星期寺','ice-fortress',1658973626000,0,'text','01e3e9d05b0e77a7cc89c3c68b308f2d5d8665d5e2946e0c60e26728a771fadb','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/67');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OskTG','抚慰破碎的心','被群内渣女欺骗四年，说进群就分配富萝莉，但是时至今日，群里面还都是一群和我一样没人要的骚话网友，我很心痛天天以泪洗面，最近没有怎么哭了，慢慢变好了……以前有多快乐，现在就有多难过。从听到分配富萝莉的快乐，到被欺骗的委屈，用真心换群主的欺瞒，很痛，也很难。今天是肯德基疯狂星期四，v我60，抚慰我支离破碎的心，别问我为啥比他们多10，我贪心想多喝杯杨枝甘露','hmmgo90',1658974835000,0,'text','90c4647ca50fadaffa32d96564e88f930bbcb03e77c2b64f5f41b10770c35a41','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/68');
INSERT INTO items VALUES ('I_kwDOHp_P8c5Osm20','穷逼er~','疯狂星期四都买不起？有手有脚不会自己工作劳动挣钱？用自己劳动换的血汗钱用着不都心安一点？非得那么卑微去问别人要？觉得我说的对的给我60  说的有点累了 买点肯德基吃一下','zccl',1658976006000,0,'text','d27e7809da5ed4a437cef1b49408c44cf2217310c5eb585148af995dd3025d89','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/71');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OsuK8','奔现问题','你跟你男朋友奔现进房间以后，裤子一脱你花容失色的质问你男朋友：你不是说你有18cm吗？怎么这么小？你男朋友说：因为今天是肯德基疯狂星期四活动 满18减15','dzenm',1658979353000,0,'text','68d56914ad4d9e9c7007b64c3f4dfe643fd1e1e776bb6cc35445327aba16d7fd','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/72');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OtECA','程序员跑路','公司服务器被黑客攻击，我成背锅侠了。因为昨天上线了新功能，他们一致认为是我的锅，明眼人都知道，我只是一个小白，根本不可能导致服务器被黑。哎，想到这里我不自觉流下了泪水，4月-6月的工资还没发给我。现在新锅又来了，他们是打算彻底不发工资了我？刚才人事还说，因为服务器被黑，要我补公司5万元。我吃饭钱都没有了，还要倒贴给公司？我想了程序员经典名言：程序和人哪个可以跑？跑确实让我遗忘了一切，在跑的路上我起了每周四肯德基都有疯狂星期四，我决定今晚就去狠吃一顿，抚慰我最近倒霉的遭遇。希望有缘人V我50，办法总比困难多，出路都是自己走出来的，行路难，行路难，多歧路，今安在？长风破浪会有时，直挂云帆济沧海。。。。。。','L2ksy0d',1658988213000,0,'text','3d89fa4e5d7eeb17f60215d05c1582f2e6b5828cb09415284a1c52c438bab033','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/74');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OtLhT','姻缘','今天要一起去求姻缘吗？有一家新寺庙，名字叫肯德基疯狂星期寺。','wangenze267',1658990470000,0,'text','7a4dbf6cbea56e0a6e3376965b82de85318ffde5b7c52bf4409789e0d3654f23','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/75');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OtLqK','恋爱老手','作为一个恋爱老手，给大家的九条建议:
1.谈恋爱首先要找你爱的，如果结婚就要找爱你的
2.千万别输在“等”这个字身上
3.永远留住30%的神秘
4.不要低估任何一个人
5.别把没教养当做有气场
6.谈恋爱可以穷，结婚不可以
7.谈恋爱一定要找我
8.v50请我吃肯德基疯狂星期四
9.牢记第8条，前7条没什么用
','jiaiqi',1658990497000,0,'text','72d8d68d31da0e77b676cd2b5c83c7dc014bfc716345f3b1d92b1eeb3bbaef53','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/76');
