INSERT INTO items VALUES ('I_kwDOHp_P8c5OtMO7','穿过挪威的森林，让我走进你的梦里','穿过挪威的森林，让我走进你的梦里，夕阳落在我的铠甲，王子不一定骑白马，现在是下午三点四十六分，你不必故作冷淡，我也不想做最后的纠缠。最后问一句，疯狂星期四，请我吃个肯德基？','wangenze267',1658990656000,0,'text','32bfb9001b8878586a1ab9d1ceb0d3ac15026425a3c83c656397ba6b7fa7f7fa','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/80');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OtUqy','李华的小作文','假如你是李华，你的英国笔友Peter给你写了一封信，向你询问你周四的安排，请你写一封回信。
写作要点:
1.你要去肯德基参加"疯狂星期四"活动。
2.向他介绍"疯狂星期四"的活动。
3.要求他V你50。
注意事项:
1.行文流畅，包含所有要点，无语法错误，可适当自由发挥,80词左右
2.不出现真实的人名地名。
3.请将Peter的50 V给我，否则不给分。

Dear Peter
I will introduce my plan in this Thursday for you，I will go to KFC and have__________________________________________________________________________________________________________________________________________________________________________________________
I''m looking forward to your reply and the V 50 from you.
Yours
LiHua','minoism',1658992817000,0,'text','ce95f0dc43a6c85c96aae6456bc06e81cff52fe8b2849b0a8903da9b23fb1fa0','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/81');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OVh3A','朋友找我借钱','我想问一下，之前朋友找我借钱，前后加起来有大概七万（够立案）但是没有借条也没有字据，微信也早已互删没有任何关于借的字眼，只有支付宝上还有转账记录，派出所刚让我把转账记录发给他看一下的时候，我点支付宝点歪了，不小心点开了肯德基，发现今天是疯狂星期四，谁请我吃？','zjw-swun',1658466275000,0,'text','eca5e301fe7469fb884e073f046cb7bd48b4f7deba2958d44aacb33217ec9870','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/9');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OVhTh','如何搞定合租女生','如何搞定合租女生
1、找一个夜里假装打电话，电话内容大约是要跟异地恋的女人分手，做暴怒痛苦状，声音要大，要让她听到。

2、过后几天装作若无其事，展现男人的刚毅。

3、找一天夜里，喝点酒回去(别真喝醉了)然后在客厅装醉，弄出点动静让她知道，最好能骗她出来扶下你，考验你演技的时候到了，扮演好一个痴情失恋男人的角色!

4、用清醒的思维演绎酒醉后故作清醒的表现，含糊不清又颇有礼貌的请她为你倒杯水。

5、甭客气,接水的时候把杯子直接掉地上去。

6、等她先蹲下或者弯腰去捡杯子的时候，抢着去捡,这个时候尝试去做部分身体接触，借此机会试探对方反应，以备下次行动方案。

7、这一夜到此结束。

8、第二天早点醒,注意隔壁动静,在她出房间的时候也出去，这个时候的你只能穿一条裤衩。在确认她已经看到你之后赶紧尴尬而略带歉意的回屋。

9、找个机会请她吃饭，表示愧疚与感谢。

10,最关键的一步来了，今天是疯狂星期四，请我吃肯德基，教你下一步骤，要快！晚了肯德基没了！','zjw-swun',1658466190000,0,'text','56c2b17fc3a013cdaac2159ffd14d1c98aa37313433fa85c5c8edc8ea7ca1d52','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/8');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OVib8','薅羊毛','有劳斯莱斯的同学，可登录劳斯莱斯APP选择中国界.面，滑动页面有一个虎年迎新春，填写手机号码，送飞天茅台53度1支。 保时捷车主公众号左下角点进去上传行驶证上的车架号就能抽奖，奖品最低300京东卡,部分同学有保时捷的可以领一下。 没有劳斯莱斯和保时捷的同学，打开肯德基APP，今天是疯狂星期四。','zjw-swun',1658466364000,0,'text','28385a838c900427a9c2350653ff94066a2f914a064ea9b3eb2b72a1674d3f86','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/11');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OViJ8','我们最终还是分手了 ','很丧 还是分手了谢谢你 
现在是4月7日
我们最终还是分手了 
很开心可以和平分手 其实从朋友一直到恋人我们之间发生了挺多事情 
能走到一起也挺不容易的 我喜欢你 很喜欢你 想和你有一个结果 想你时会不自觉嘴角上扬 听到别人说你的名字会突然变得沉默 

独自一人在夜里时会想你想到失眠 我总在问自己为什么还坚持 可是没有答案 

但我只知道放下你我做不到 有时候就像神经病 因为种种原因我的性格养成的有点怪 会因为赌气冷战或者莫名提不起兴趣 看到你不知道回复什么就刷表情 我也挺无助的 我不是孤立而是有时候我会想很久应该回什么 

你如果也是真的喜欢我就请你别离开我虽然我不一定能让你很开心 我不一定完美 可是你在我会很安心 想伸手抱抱你想为你做很多想为你分担一些孤单 想知道你所有痛苦来源想知道你所有烦心事想知道你喜欢什么讨厌什么 想知道你最爱谁讨厌谁 想了解你依赖你我会一直陪着你的 你需要我就在 

我没有备胎 也不玩暧昧 我所有的温暖和宽容 眼泪和笑容 好坏脾气孩子气都给了你 痛苦来源想知道你所有烦心事 想知道你喜欢什么讨厌什么 想知道你最爱谁讨厌谁 想了解你依赖你我会一直陪着你的 你需要我就在 

谢谢关心我的好朋友
也不知道谁写的挺感人就随手复制下来了 
该复制的都复制了 就剩最后一句  
今天天气好冷
能请我疯狂星期四吗？','zjw-swun',1658466321000,0,'text','868b87e7830a9a90c1607e978acfc51b7e2f07f65b1bdf08699053fb8207bd6a','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/10');
