INSERT INTO items VALUES ('I_kwDOHp_P8c5OVjaj','群主欺骗我','被群主欺骗两年多，说进群就分配女朋友，但是时至今日群里面还都是一群和我一样没人要的骚话网友，我很心痛天天以泪洗面，最近没有怎么哭了，慢慢变好了……以前有多快乐，现在就有多难过。从听到分配女朋友的快乐，到被欺骗的委屈，用真心换群主的欺瞒，很痛，也很难。今天是肯德基疯狂星期四，v我140，抚慰我支离破碎的心💔，我不喝饮料','zjw-swun',1658466514000,0,'text','c8183f1a43c736062d8bdbd37636c377dc06c41a8e4a9964868126cf218c5622','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/13');
