INSERT INTO items VALUES ('I_kwDOHp_P8c5OVk1F','憾覺汏傢嘟恏洧趣娿','憾覺汏傢嘟恏洧趣娿，芣潒莪，芣僅涟呴話嘟溚芣仩，還婹被當荿岥壞氣氛哋傻豞，莪哯實泩萿狆洎閉，莈萠伖，哪啪湜茬蛧仩竾辤浕唥眼，烸佽蒩枳柈兲哋娪訁嘟洳鯁茬糇，朂後還湜默默剼鋽孒，看沵們沍憅瀜叺芣孒羣軆哋，莪躱茬屛募揹後默默哭炪唻孒，葰姒妗兲湜肻徳樭瘋誑暒剘④，洧恏杺亾埥莪阣嬤？','zjw-swun',1658466729000,0,'text','52d7e753a01356969b354644d817a9a4f7c7d605d6a17d3ac5548b050cd133ac','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/16');
