INSERT INTO items VALUES ('I_kwDOHp_P8c5OWD08','来说一下关于我的瓜吧 ①首先谢谢大家对这件事情的关心。我事先根本没有想到会这样既然已经出这件事情了，那我不如直接讲清楚吧。也不是博得大家的同情什么的，只是回应一下。 ②那人所发出来的聊天记录、照片、视频、甚至那些亲昵称呼都是真的，无一造假。可我从未将这些东西流传在任何网络平台上面，至于那个人是怎么有的，我也不清楚。 ③虽然这事出了，但我没有不尊重任何人，我不认为我有错，所以我不会认错。 ④最后，想知道到底发生了什么的，微信转我88肯德基疯狂星期四，我把故事从头到尾给你编一遍','来说一下关于我的瓜吧
①首先谢谢大家对这件事情的关心。我事先根本没有想到会这样既然已经出这件事情了，那我不如直接讲清楚吧。也不是博得大家的同情什么的，只是回应一下。
②那人所发出来的聊天记录、照片、视频、甚至那些亲昵称呼都是真的，无一造假。可我从未将这些东西流传在任何网络平台上面，至于那个人是怎么有的，我也不清楚。
③虽然这事出了，但我没有不尊重任何人，我不认为我有错，所以我不会认错。
④最后，想知道到底发生了什么的，微信转我88肯德基疯狂星期四，我把故事从头到尾给你编一遍','h7ml',1658471209000,0,'text','6ce094db703311f04e4d8ef183c0bdba095f148d4c9b649ec53c6be82553b720','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/23');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OWD68','世界上现在77亿人，有253亿只鸡，是人的数量的三倍。也就是说，如果鸡决定与人类开战，每个人平均要打三只鸡。请记住，不管你有多么孤独，这世界上的某个角落里有三只鸡是需要你去对抗的，就算它们死了，立刻又会有同类补上，就算你一个朋友都没有，你还有三只鸡做敌人。今天是肯德基疯狂星期四，V我50，我帮你去杀敌','世界上现在77亿人，有253亿只鸡，是人的数量的三倍。也就是说，如果鸡决定与人类开战，每个人平均要打三只鸡。请记住，不管你有多么孤独，这世界上的某个角落里有三只鸡是需要你去对抗的，就算它们死了，立刻又会有同类补上，就算你一个朋友都没有，你还有三只鸡做敌人。今天是肯德基疯狂星期四，V我50，我帮你去杀敌','h7ml',1658471222000,0,'text','cea4d7c92c32513fee289ebed64489fd743e57fbff33da097b03cfe8183e91ee','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/24');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OWDee','和你分手20年了，你还是那个能影响我情绪的人，我还留着我们的合影，还记得你的生日，我有过无数次想去找你的冲动，可还是忍住了，这条消息我不屏蔽你，因为我是你永远的黑名单，可是我爱你，从过去到现在，整整爱了你二十八年，但是，现在我一点也不难过，因为我压根不知道这是谁写的，也不知道这女孩是谁，我只是想顺便告诉你：今天疯狂星期四，我想吃肯德基','和你分手20年了，你还是那个能影响我情绪的人，我还留着我们的合影，还记得你的生日，我有过无数次想去找你的冲动，可还是忍住了，这条消息我不屏蔽你，因为我是你永远的黑名单，可是我爱你，从过去到现在，整整爱了你二十八年，但是，现在我一点也不难过，因为我压根不知道这是谁写的，也不知道这女孩是谁，我只是想顺便告诉你：今天疯狂星期四，我想吃肯德基','h7ml',1658471163000,0,'text','088a5325f97d2e51d87c5b7ead7bcda4ff5c15d52c6b08f2dcc7fab74ccad9c5','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/21');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OWDwI','扒个群里的渣男，我有个朋友被群友睡了，大概是三个月以前吧，我朋友在群里认识了一个男的，他们在网上聊了差不多两个星期左右就见面了，而且第一次见面就去宾馆了，之后的每个星期六星期天都会去，就这样持续了好几个月。我朋友给那个男的说，已经一个多月没来大姨妈了，想不到这句话说完，隔天就找不到那个男的了，手机一直打不通，关机，直到我朋友前几天跟她父母坦白这件事情，我朋友就在旁边一直哭，那天晚上我偷偷给她买了个验孕棒一看，真怀孕了。然后我第二天请假一天，专门给她聊这个事，她说那个男的对她很好很好什么的，我说对你好还不是想玩你，实在不行报警吧，她当时听完这句话就趴桌子上大哭。正当我打开手机想报警的时候，不小心打开了肯德基，想起来今天原来是疯狂星期四，所以说谁请我肯德基?吃完我继续说。。。','扒个群里的渣男，我有个朋友被群友睡了，大概是三个月以前吧，我朋友在群里认识了一个男的，他们在网上聊了差不多两个星期左右就见面了，而且第一次见面就去宾馆了，之后的每个星期六星期天都会去，就这样持续了好几个月。我朋友给那个男的说，已经一个多月没来大姨妈了，想不到这句话说完，隔天就找不到那个男的了，手机一直打不通，关机，直到我朋友前几天跟她父母坦白这件事情，我朋友就在旁边一直哭，那天晚上我偷偷给她买了个验孕棒一看，真怀孕了。然后我第二天请假一天，专门给她聊这个事，她说那个男的对她很好很好什么的，我说对你好还不是想玩你，实在不行报警吧，她当时听完这句话就趴桌子上大哭。正当我打开手机想报警的时候，不小心打开了肯德基，想起来今天原来是疯狂星期四，所以说谁请我肯德基?吃完我继续说。。。','h7ml',1658471200000,0,'text','654a9fed1db5d8bbd303cc7f31565ad00eff678a7f48902e650e2f86735f6f49','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/22');
INSERT INTO items VALUES ('I_kwDOHp_P8c5oycul','我是维吉尔，今天下午我就要和但丁决战了，但是因为大排档一直不开张，囊中羞涩，没钱买椅子，V我五十，我吃饱了用阎魔刀打爆但丁','我是维吉尔，今天下午我就要和但丁决战了，但是因为大排档一直不开张，囊中羞涩，没钱买椅子，V我五十，我吃饱了用阎魔刀打爆但丁','SleepyAsh0191',1686806272000,0,'text','7eabeb58f3b9f4cbcc7007f1ff0a237a3e921d531f9aff375fbe67c5d5331158','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/171');
INSERT INTO items VALUES ('I_kwDOHp_P8c5OyDFW','图穷匕见','感觉大家好有趣啊，不像我，不仅连句话都搭不上，还要被当成破坏氛围的傻狗,我现实生活中自闭没朋友，哪怕是在网上也受尽冷眼，每次组织了半天的语言都如鲠在喉，最后还是默默删掉了看你们互动，融入不了群体的我还是想偷偷问：今天是肯德基疯狂星期四，能有好心人请我吃吗？','brcarry',1659068641000,0,'text','f0aef9812e1c555c2c4f18cdd82296d7122e9d384220534a3dd3496666a3cd15','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/83');
