INSERT INTO items VALUES ('I_kwDOHp_P8c5PmGA2','我是你姐！','姐我再说一遍，你是我姐，你不是粉丝，你不要再让我听到，你说你是粉丝，这两个字我不要再听到了，听到没有，我再给你说一遍，如果你再敢质疑这个，就v我50吃肯德基疯狂星期四','zccl',1660183702000,0,'text','4a4660b18ace4b4163b96c6cc651fcc6180b2f1bc369400e6b0463f06338b48e','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/95');
INSERT INTO items VALUES ('I_kwDOHp_P8c5PnL_D','肯德基这逼养的，怎么又到了周四','肯德基这 beyond 的，怎么又到了周四，这一次，肯德基疯狂星期四，我一定要吃，我本是显赫世家的少爷，却被诡计多端的奸人所害！家人弃我！师门逐我！甚至断我灵脉!重生一世，今天肯德基疯狂星期四!谁请我吃？家人们，别他妈垂头丧气了 知道今天是什么日子吗？今天是肯德基fucking crazy Thursday！吮指原味鸡10块钱2个 ，家人们v我100，我他妈要吃20个！','minoism',1660208585000,0,'text','c28a1cdfdb824869186f06d6d439d012f0791facb673051b6a5462edca15114f','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/97');
INSERT INTO items VALUES ('I_kwDOHp_P8c5PnL1p','今天，是我人生中最黑暗','今天，是我人生中最黑暗、最emo的时候，但是我很难把朋友当成垃圾桶或者树洞去倾诉，更喜欢憋着自己消化，睡一觉第二天醒来就好了，不想连累别人，不想把负面情绪传递给身边的朋友。但是，我更希望家人能够给予我物质层面的帮助！今天是肯德基疯狂星期四，有哪个家人愿意请我吃肯德基吗？','minoism',1660208554000,0,'text','7d566bb0c252a7d36a20d8eaf14bb1f211dd8be3a67ea2fe9634450359b8a763','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/96');
INSERT INTO items VALUES ('I_kwDOHp_P8c5PXhBg','我本是显赫世家的奥特曼，却被诡计多端的怪兽所害！奥特曼家族弃我！奥特之父逐我！甚至断我伽马射线！重生一世，今天肯德基疯狂星期四！谁请我吃？','\u6211\u672c\u662f\u663e\u8d6b\u4e16\u5bb6\u7684\u5965\u7279\u66fc\uff0c\u5374\u88ab\u8be1\u8ba1\u591a\u7aef\u7684\u602a\u517d\u6240\u5bb3\uff01\u5965\u7279\u66fc\u5bb6\u65cf\u5f03\u6211\uff01\u5965\u7279\u4e4b\u7236\u9010\u6211\uff01\u751a\u81f3\u65ad\u6211\u4f3d\u9a6c\u5c04\u7ebf\uff01\u91cd\u751f\u4e00\u4e16\uff0c\u4eca\u5929\u80af\u5fb7\u57fa\u75af\u72c2\u661f\u671f\u56db\uff01\u8c01\u8bf7\u6211\u5403\uff1f','4O4NtFd',1659949639000,0,'text','f8c0e58693c70bd20f4da6dbb62377a7336d7144ce984ed3ffef6705316e049c','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/94');
INSERT INTO items VALUES ('I_kwDOHp_P8c5QfLnM','8月24日疯狂星期四文案（dota版）','我不知道什么文案，不知道什么kfc，也许今天是疯狂星期四但你不会v我50，但你要记住:今天是ame水人波高地四周年纪念日！','yutian-9264',1661405910000,0,'text','1a6c38e546254f70387f27b55244252bb4f8cc30dc9c29cf0e0a3ee5be02cb7b','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/99');
INSERT INTO items VALUES ('I_kwDOHp_P8c5qHk7n','还是会想你','距离上次见面已经过去1年4天21小时，我还是常常会想起你，想起你嘴角弯弯勾起的样子，想起我对你第一次心动的心跳，我很想忘记你，我自卑，懦弱不堪，根本配不上你，高考后，如愿，我们去了两所不同的大学，当我还是想你，我没有离你太远，我怕我对你的思恋，将我撕碎，不在一所学校，听不到你的声音，闻不到你的气息，看不到你的笑脸盈盈的样子，我好嫉妒你的朋友，因为他们可以随便触碰我渴望不可及的东西，我好想，我好想！我好想和你在一起。bro，V我50，我带她去KFC-Crazy-Thursday','XiZu233',1688027482000,0,'text','a4a4eb37b75e9380173661459f034c95a5e66dc85b411eca185094f4cc477e12','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/173');
INSERT INTO items VALUES ('I_kwDOHp_P8c5qHvJe','蔡徐坤道歉声明','我是蔡徐坤，我对我过去的行为感到深深的悔恨和自责。我承认我曾经和一位女生发生过不负责任的关系，导致她怀孕，并且在我的强烈要求下，她选择了打胎。这是我人生中最大的错误，也是我最无法原谅自己的罪过。我对那位女生造成的伤害，无法用言语来表达，我只能说，对不起，真的对不起。我知道我的道歉无法弥补她的创伤，也无法挽回她的信任，但我还是希望她能够原谅我，给我一个改过自新的机会。我也希望我的粉丝们能够理解我，不要因为我的错误而失望或者受到影响。我会努力做一个更好的人，更好的歌手，今天是肯德基疯狂星期四，请随机一个粉丝v我50，我会用我的音乐来回报你们的支持和爱。谢谢大家。','Kahen',1688029161000,0,'text','0ebe69c4e4201b0f1e9b5ae6cc61931fedc5af93da061c82210d184e9dad9261','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/174');
INSERT INTO items VALUES ('I_kwDOHp_P8c5R5Ofc','羊了个羊设计师','我是羊了个羊的游戏设计师 今天我被公司开除了 因为我掌握着第二关的通关密码 所有人都追着我 我现在无处可藏 只能向你求助 今天疯狂星期四 你V我 50 我就把羊了个羊第二关的通关秘籍传给你','rin0chan',1663220423000,0,'text','fa82d60884d6985110c56fb45631c24d0878f626d5ab43863463905ecd75c763','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/105');
INSERT INTO items VALUES ('I_kwDOHp_P8c5R6ltH','小作文','我其实真的很想你会回来 我在深夜想起你的时候还是会忍不住掉眼泪 消息写了又删 我也在你离开的时候拼命挽回过 这辈子最大的遗憾就是没能和你走到最后 答应过你的好多事都还没有完成 要是能在结婚的年纪遇见你就好了 我觉得这个世界好不公平真心总是被辜负 我求你回来的样子一定很烦吧 这些天写了很多话 想着哪天给你看看 想让你知道我这些天怎么过来的 你以前问我跟你在一起后不后悔 说实话我没有后悔 因为只要是我喜欢的不管好不好我都会把我最好的给你 我已经习惯有你的每一天 你走了 离开了 不要我了 我每天就像个废人一样抽烟喝酒 我以为这样就能消磨对你的思念 可是我每次喝醉了想到的人是你 可能觉得我特别没出息吧 我们不是不合适 每个人的性格不一样互相磨合互相体谅互相包容 有些时候吵架和你冷战 不是因为我不爱了而是当时的我不知道怎么去跟你沟通 我没有那个能力 我不知道怎么去说去解释才能让你明白我的意思 我不知道怎么做才能和你的想法达成一致 往往好多时候 我们吵架就愈演愈烈了 每次吵完都会后悔好久 为什么当时就不能理智一点 控制自己的脾气不和你争吵 为什么不多包容你 我其实心里会想很多 我不说我比别人爱你 我只能说只要你一句话不管多远我来会来见你 你让我做什么我都满足你 你走后我的世界就剩我一个人了 心里空空荡荡的 整天做什么失魂落魄的 失去的不会再回来 错过的终究不会再遇见 大概不打扰才是最后的温柔 毕竟有些感情除了说再见别无选择 本以为陪我到最后的人一定是你 所以我把自己全部的感情全部投入到你的身上 一切时间一切精力都放在你身上 爱的太满结果陪我一生的人却不是你 你知道那种感觉吗 每天晚上我都会胡思乱想很多以前有你的时候 想起我们以前快乐的事 我真的很脆弱你走了我的世界都要崩塌了 夜里睡着突然被惊醒的那种感觉那种快要窒息的感觉 我比谁都喜欢你 但是没有用啊 我不知道这些天是怎么熬过的每天丧到极致做什么都会想到你 每天沉沦在明明知道没希望还要无尽的等待整夜失眠 我每天都幻想着你会来找我 很想知道你的近况 爱而不得的感受真的太难受了 很庆幸我能走到你的身边 却没能给你一个家 以前老是说会保护你会给你安全感 后来你说我不是你想要的 原来真的有两个人 要相互喜欢 感谢你出现再我的生命中 跟你在一起的那些时间我真的特别的开心  所以今天可以微信转给我五十块钱吃肯德基吗','rin0chan',1663238328000,0,'text','59cff9bf3e9577ea5856487523c7c91b12c6500aa8f4da814c52de5bef79685f','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/106');
