INSERT INTO items VALUES ('I_kwDOHp_P8c5RYoLR','iPhone14版','14不香了，果然还是13更香，iPhone14真是更新了个寂寞！你看过iPhone14发布会了吗？多少会有些失望，iPhone14真是更新了个寂寞啊，除了eSIM卡和卫星通讯两张无关痛痒的更新，其实纯粹就是数字变化，从13到14，采用了13相同的A15芯片，相同尺寸的屏幕，这也能叫全新一代的iPhone14手机，这无疑是妥妥的智商税！近期准备换机的那些人，反正我不建议购买iPhone14，不如把钱拿来放在填饱肚子上，今天肯德基疯狂星期四，谁请我吃？','yutian-9264',1662602016000,0,'text','848942fdefa4a172932df91970f0c28f2fdd388e1bc3f653502b38fc78876d13','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/102');
INSERT INTO items VALUES ('I_kwDOHp_P8c5RZBPd','友谊',' 如果你现在买iPhone14和一块苹果手表。你就不会有朋友。其他人都会只会尊敬你，和你说客套话。你永远不可能和他们嬉笑打闹。除了礼貌的微笑，你得不到任何东西。你会孤独的走进坟墓。没人陪你。这就是我现在不买iPhone14和苹果手表的理由。 但如果有朋友v我五十块让我去肯德基疯狂星期四，我们就会建立起最纯真最坚固的友谊，收获一片真心。所以你现在买iPhone14和苹果手表不如v我50一起疯狂星期四。​
