INSERT INTO items VALUES ('I_kwDOHp_P8c5S3wnj','矿产故事','从前有一个国王叫肯，娶了一个歌姬为妾。国王的国家矿产资源发达，国王十分宠爱歌姬，将一部分矿产给了歌姬的家族开发。但歌姬十分贪婪，为了实现矿产垄断，歌姬把其他同行的矿井都给封了，包括国王分派给贴身武士的。于是国王把歌姬抓起来审判，歌姬问定什么罪？国王说：死罪。肯的姬封矿刑期死，为我武士。','JanFrank',1664434300000,0,'text','582374e0295defd488d59425f5461a71b1bc87bd23ee46675c778a2e15e22f4b','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/114');
