INSERT INTO items VALUES ('I_kwDOHp_P8c5sGj3p','意大利面 42号混凝土','xray有孩子这件事，我觉得和勾股定理是有关系的，热带雨林的蝴蝶煽动了翅膀导致了大气逆辐射的增加，这使得春天来临的速度加快，春天来的快就会让鸡交配更快，更快就意味着未来更多的鸡肉，这能使得肯德基持续采取疯狂星期X的计划，这个时候，由于厄尔尼诺的效应，产生了伽马射线，这样我们才能让xray生出更多的疯狂星期四，得出结论：V我50','SleepyAsh0191',1689848797000,0,'text','086d568ce7d0adcffa0df285d062741a80cc1c42151d8b3d49009abf841b3089','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/175');
INSERT INTO items VALUES ('I_kwDOHp_P8c5SW-ze','宛瑜告别版','亲爱的展博：当你看到这封信的时候，我已经在去机场的路上了，请原谅我改签了航班，我知道如果我看到你们肯定就走不了了，因为我舍不得你们每个人，尤其是你，和大家在一起的日子，是我一生中最快乐的时光，虽然我也不想结束，但是新的故事总要开始，展博过去我不懂爱是什么，是你让我明白，爱是当你爱上一个人会舍弃自己的自由换取他的自由，爱是当你爱上一个人会改变自己的人生，成全他的心愿，爱是当你爱上一个人会愿意放开手，留下最好的回忆和祝福，爱情最美的，不一定是终点，旅途一起走过，也以不负一生，原谅我的天真，这是我能想到的，最好的结局。如果你想我了，请v我50一起吃顿炸鸡。','yutian-9264',1663815757000,0,'text','fbcd44efb604727401df00fdd882ad1a3dc31db129b6ed0ac57844271647e0f5','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/108');
