INSERT INTO items VALUES ('I_kwDOHp_P8c5t8uyH','xxx','THU 大学的 Crazy 教授实验室初步分析表明氟碳化钾极有可能是一种更经济的常温常压超导体，制作成本相对较低的同时在296K,1bar下依然表现出可实用的超导特性。不巧我们的仪器维护状态欠佳，阻碍了样品更大规模的制备。现在只需要赞助我们实验室＄7.0053即可获得天使赞助者身份，并在之后的大规模专利应用阶段获取相应分红。','krzhck',1691654366000,0,'text','e77df71459d8f0cdb977a5c26358f82d1b4bc002fa08517bf04b7d2961f24f53','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/177');
INSERT INTO items VALUES ('I_kwDOHp_P8c5t9Hov','111','千万不要网恋，去年8月份结的婚，今天离了，才结婚一年左右说说我的情况，希望玩游戏的你不要踩雷。我和他，在一起玩了几个月。王者、打双排啊玩各种模式啊这些都在一起，每天都互相点外卖晚上睡觉还连麦。之后就奔现谈了几个月。真的，这几个月他给了我很舒服的感觉，双方感觉都很合适，就商量着结婚，结婚不容易啊，先是货款买了房，然后又是装修、办酒，结个婚几平把存的钱花的七七八八。心想结婚了那就好好生活过日子吧，游戏我也不准备玩了。万万没想到，之前对我那么好的他竟然一结完婚就跟变了个人似的，家务活都是我做，他还在游戏里又找了个固玩。我一个月能有大概5000 左右的收入，这钱 用来每月还房贷和日常开销，剩下的都会存起来，其实我不介意他每天打游戏，因为我也爱打游戏，其至他在游戏里小号给其他人充钱也没事。这次离婚的导火线是我发现银行卡无缘无故用了50块，就问他钱哪去了，他说他给他固玩买了麦当劳的套餐，说麦当劳的炸鸡专业性最强，我当场就给了他两耳光。要是别的我也就忍了，周四你跟我说麦当劳炸鸡最强？大家说，周四哪家炸鸡最强？肯定是KFC啊！v我50抚慰我受伤的心灵🥹','krzhck',1691658252000,0,'text','280ec1743ea84c73f6069f691c414a8e41aa9f34046316b7fd4faef5b74fcb0e','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/178');
