INSERT INTO items VALUES ('I_kwDOHp_P8c5TX16-','肯德基这byd，怎么又到了周四','肯德基这逼养的，怎么又到了周四，这一次，肯德基疯狂星期四，我一定要吃，我本是显赫世家的少爷，却被诡计多端的奸人所害！家人弃我！师门逐我！甚至断我灵脉！重生一世，今天肯德基疯狂星期四！谁请我吃？家人们，别他妈垂头丧气了！知道今天是什么日子吗？今天是肯德基fucking crazy Thursday！吮指原味鸡10块钱2个，家人们v我100，我他妈要吃20个！','SleepyAsh0191',1665030170000,0,'text','e00794bf005827b4886d427a3772f4e77fdf1d643f2ae9925c4d3d4ebba40dc3','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/120');
INSERT INTO items VALUES ('I_kwDOHp_P8c5TX1pz','姐妹','姐妹抱抱你，我看了也很气，这件事闹得挺大的，但也不是特别大，你要说小吧，倒也不是特别小，我觉得这事还是挺大的，不过不是特别大，但也不小。大家都觉得这事特别大，但我觉得也没那么大，但你要说小吧，也不小。到底是啥事儿，v我50，我今天亲自去肯德基看看。','SleepyAsh0191',1665030079000,0,'text','859949ce99233792d66d8398aa8508a118eb317d92f19a723a3ea08f9612134c','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/119');
INSERT INTO items VALUES ('I_kwDOHp_P8c5TX1Y-','葡式蛋挞','某个人，不回消息永远别回了，到底群消息重要还是我重要，整个群我只对你一个人有感觉，难道你心里就不明白吗？不然我整天闲得来这里聊天，我不会跑别的地方聊天玩吗？你以为我天天闲得慌吗？我如此的喜欢你，今天肯德基疯狂星期四葡式蛋挞29.9八个，你还有机会挽回','SleepyAsh0191',1665029994000,0,'text','f0bfdbb8e83cad8f0775fe29bbdb35a27bcfb1a4b7fc7763929d35ac3270e42e','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/118');
INSERT INTO items VALUES ('I_kwDOHp_P8c5TX29Z','我超，原！','你好，金色的那菈，我是兰德基，我听兰阿帕斯、兰萨卡、兰茶荼、兰非拉他们说，你愿意为无忧节做准备，我现在正在进行「烹饪修行」，肯德基，疯狂星期四，是开心的味道，​V我5​0，让新的梦想永远不被无留陀侵蚀，旧的故事与无留陀一同被忘却，森林会记住好那菈的善举','SleepyAsh0191',1665030517000,0,'text','0936a347aa581dfff25469658665ac40d8d5a1237bb230c717cf93f64115f91d','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/124');
INSERT INTO items VALUES ('I_kwDOHp_P8c5TX2DG','正确约炮的标准流程','正确约炮的标准流程：一般都上午10点以后，女的打扮打扮，男的取点钱，见面了，女的假装不好意思，男的一般都夸女的比照片好看，然后问女的爱吃啥，就领吃饭去了，男的开始展示自己的幽默然后溜达，看电影，一晃一下午女的也不说回家。男的寻思这是没跟我呆够啊，就说咱俩唱歌去吧，女的说太晚了，男的说没事一会我送你回家。一般这阶段男的不会把女的咋地，这时候时间也有点晚了，男的说走吧我送你回家，女的还得寻思，这男的是没看上我啊，心里有点小失落两人心里就开始寻思怎么能不回家。男的说这么晚了，你回家我也不放心啊，我有点没待够，女的说我必须得回家，男的说我送你，结果两人墨迹墨迹的10分钟没走几米。后来女的说我回不去家了，理由可能是寝室关门了，或者朋友对象回来了，男的一本正经的说，要不我给你找个宾馆吧，女的说，不过你得答应不碰我，男的说，放心吧，我不是坏人，然后微微一笑深藏功与名。然后两人就进宾馆了，先聊会天看会电视，男人时不时的说女的，你长的真好看，男的说，你明天还上班或者上学，早点睡吧，女的还得装不好意思，男的说我能抱着你睡么，什么也不干。女的说行，男的就狠狠的抱着女的说，亲爱的，我这么抱着你，你就不冷了，女的也抱上了，男的说我可以亲你吗，女的也默认了，可是一般这时候还不会发生啥。这时候男的想有进一步的动作，开始脱女的衣服，脱到底线，女的这时候开始拒绝，推开这个男的，男的一看情行不行，就说宝贝对不起，我太冲动了，你要知道我是个男的，何况你还长的这么好看。女的这时候就把男的当亲人，讲述自己情路坎坷，人生迷茫，男的这时候就开始展现自己的温柔，宝贝你要是早遇见我就好了，一定不会让你吃这么多苦，你别怕，还有我呢。突破了女的的心灵防线，大家就都放的开了，女的开始亲男的，然后男的翻身小声说道：今天肯德基疯狂星期四可以请我吃嘛？','SleepyAsh0191',1665030211000,0,'text','e7c9424fb1c24360b022abd541510605a954c0b4088eeea67fce1f36831f8ef4','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/121');
