INSERT INTO items VALUES ('I_kwDOHp_P8c5TXz5A','藏头诗 临江仙•抒怀','临江仙•抒怀
疯语薄言悲复喜，
狂了营营此生。
星低云阔夜流空。
期年终碌碌，
四季苦匆匆。
