INSERT INTO items VALUES ('I_kwDOHp_P8c5U8aYh','你好，我是樱井孝宏，近日有人称我有长达十年的婚外情，我想澄清这完全是误会。这件事严重影响了我的日常生活和职业生涯，所以我必须去把这件事处理好，由于总是来回奔波，今天出门忘记带钱了，现在肚子很饿，v我50，等我吃饱了我继续解决这件事，事情结束后给你们每个人都可以随便把声优和角色联系在一起，我不会有意见的。','你好，我是樱井孝宏，近日有人称我有长达十年的婚外情，我想澄清这完全是误会。这件事严重影响了我的日常生活和职业生涯，所以我必须去把这件事处理好，由于总是来回奔波，今天出门忘记带钱了，现在肚子很饿，v我50，等我吃饱了我继续解决这件事，事情结束后给你们每个人都可以随便把声优和角色联系在一起，我不会有意见的。','SleepyAsh0191',1666853447000,0,'text','935be8bad050c21d47929bf6e9ae9dc8f09d4f0ece37b732f1b2ed7f52d518d0','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/134');
INSERT INTO items VALUES ('I_kwDOHp_P8c5U8gGx','网恋靠谱吗？','网恋靠谱吗？
当虚拟主播认识了一位v，我们聊了大半年，一直聊的都很好，突然她提出要见一面，我犹豫了说我是残疾人，她说她不介意，只做普通朋友，于是我答应了，也要了她的塔照，普普通通的一个人，看起来不讨厌，她离我的城市不远…我们约在海边见面，没有选择商场怕遇到林忆宁，我先到的因为她要开车好几个小时，等待时看着照片以为会是“翻车现场”因为手机都有美颜功能，但是当她走出停车场时我一眼就认出她了，她本人比照片上好看多了，也是我特欣赏的类型，她也认出我了，我不知道该说什么就站在那里，为了打破尴尬，她提议抱一下吧，我说好，但是她很礼貌的摸了摸我头喊了一句离岛姐姐。我一下子就脸红了，心怦怦的直跳，沿着海边走了会我们去吃了饭，她基本没吃多少，整个过程中都在给我剥虾皮，挑鱼刺，吃完饭走出饭店她牵起了我的手，我也没有挣脱开，她说送我回家，怕出来太长时间不播不好，我说我会飞回去很快，她执意要送，把我送到家附近公交站台，下车时她说喜欢我，从来没有当面被表白，当时我有点懵，有点感动，v我50继续给你讲
','SleepyAsh0191',1666854707000,0,'text','cbae6324f26fa14b2146545ae39df076f74cbe0927c9f4ab61d1e3d5e06fa5a8','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/136');
