INSERT INTO items VALUES ('I_kwDOHp_P8c5Wm1-5','魔兽世界停运（长文本）','亲爱的玩家：
自上线以来，《魔兽世界》收获了许多玩家的喜爱。与玩家们结下了深厚的友谊，经常打成一片，非常感谢玩家们一路以来的陪伴与支持。
但由于多方原因，我们不得不遗憾地向大家宣布，《魔兽世界》将于2022年12月24日8:00起正式停止运营。
即日起至停止运营服务前，玩家们仍可正常进行游戏。从今日起，每周四10:00我们将给在线发放代金券作为陪伴礼，玩家可前往邮件领取。我们由衷地希望这段携手共度的时光，能够给各位玩家留下美好的回忆。
具体关服相关事宜流程安排时间表如下，请各位玩家留意：
1. 2022年11月20日8点，停止游戏充值和新用户注册；
2. 2023年1月23日凌晨0点，正式停止游戏运营、关闭游戏服务器；
3. 2023年2月17日下午2点，社区关闭、官方微博账号关闭、游戏官网下架。
*请注意：游戏服务器关闭后，玩家无法再次登录游戏，游戏内的所有帐号数据及角色资料等信息将被全部清空。
对于《魔兽世界》停止运营给玩家造成的不便，我们表示深深的歉意与遗憾。终止线上运营后的其他相关补偿方案，我们将会在后续的正式补偿公告中详细说明，还请各位玩家留意后续公告。如您对停运事宜有任何疑问或建议，可以v我50边请我一顿KFC边向我反馈。
再次感谢玩家们一路以来的支持与厚爱。
','SleepyAsh0191',1668678068000,0,'text','3cfe060647de032fe2cf8ae5736a7cdc451c3a04a36f573bd83ec44bbf724c0b','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/140');
