INSERT INTO items VALUES ('I_kwDOHp_P8c5XpyCD','填空题','为防止群友长期摸鱼导致变笨，特此准备了几道题考考群友！
1.至今思项羽，不（）过江东。
2.阳春布（）泽，万物生光辉。
3.书籍是人类进步的阶梯。——高尔（ ）
4.世人笑我太（）癫，我笑他人看不穿。
5.老夫聊发少年（），左牵黄，右擎苍。
6.危楼高百尺，手可摘（）辰。
7.君问归期未有（ ），巴山夜雨涨秋池。
8.（ ）面边声连角起，千嶂里，长烟落日孤城闭。
9.料峭春风吹酒醒,（ ）冷,山头斜照却相迎。
10.（ ）闻琵琶已叹息，又闻此语重唧唧。
11.锦瑟无端（）（）弦，一弦一柱思华年。','SleepyAsh0191',1669862466000,0,'text','4ad62f7ed7e259daa9b895e2fe82ff95e9cf9d83e2cc61babba3cc3c119e5191','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/141');
INSERT INTO items VALUES ('I_kwDOHp_P8c5ZRMK3','方丈说了九个字挽救了全寺僧侣并使朱元璋龙颜大悦','1378年，朱元璋回乡祭祖来到一个寺庙，正准备烧香，他突然发问：“朕需要跪吗？” 众人顿时鸦雀无声不知所措，只有方丈上前一步说了九个字，挽救了全寺僧侣并使朱元璋龙颜大悦！方丈说的是：
