INSERT INTO items VALUES ('I_kwDOHp_P8c5ZyGIO','紧跟时事的lex语录','我什么都没做错！😫唯一做错的就是我想吃肯德基！🤗都是你逼我的！✊🏻都是你逼我谈吃别的快唱！🤐都是你逼我不吃疯狂星期四！👰是我吃肯德基你就一哭二闹三上吊的！👿我实在是想吃疯狂星期四！我也没想过每周都吃！🍻后来是你逼着我想天天吃！天天跟我说要吃翅桶！要翅桶！👧🏻明明你之前说你不想吃肯德基！不想要翅桶！👶🏻怎么又想吃了！怎么又要翅桶了！你有完没完啊！😭能不能V我50😭','SleepyAsh0191',1671629557000,0,'text','8905fdd7b36b7c2958d5eaed3aa30c4b5ce4261d72ce7d4ba19d42f13a1746cf','https://github.com/rin0chan/KFC-Crazy-Thursday/issues/143');
