INSERT INTO items VALUES ('I_kwDOLrzjj86bn-KT','你跟我说哪里贵了？','你跟我说哪里贵了？这么多年都是这个价格， 疯狂星期四 一直都是V我50不要睁着眼睛乱说，炸鸡行业很难的好不好，而且KFC真的不是随便是个人就让你V我50的，我吃KFC这么多年，我是最了解他的真的这么多年都是V我50加多5块还能多两瓶饮料在V50再补够100就够三个人吃了真的哪里贵了？！有的时候找找自己原因，好吧！这么多年工资涨没涨，有没有认真工作？这么多年都是这个价格！我真的快疯掉了！！！','zkl2333',1729760985000,0,'text','1930fa64ec6a6e187eb9328ca375531469124fa4d8bd003ec8dd864893a8a300','https://github.com/vme-im/vme-content/issues/76');
