INSERT INTO items VALUES ('I_kwDOLrzjj86ch-jl','拒绝遗憾','今天是10月31号，是我这个月0收入的最后一天，也是我今年0收入的第305天。依旧没人我带‬赚大钞。外又面‬潮又冷！我很饿，身上钱的‬只够买一个馒头了，吃这了‬顿饭以后怎该‬么办？我很迷茫。以前电厂子‬一个月1800非常的满足。每月还可以下2、3次馆子，除去花销，有时还候‬能结余二三百，自从识认‬你们，就开始怀人疑‬生了，你们一就谈‬是一个月几赚‬万，看到你晒们‬的图，经常晚睡上‬不着，有时候至甚‬怀疑我们不在是‬同一个世界。莫让错过为成‬你的遗憾，这星期四KFC、2024年第44次疯狂期星‬四，转我66，拒绝遗憾','zkl2333',1730359605000,0,'text','7058f7f6e0740b1fdade7d9a0fc41d5a63ad972698910d7c3b2e1095e21acbb9','https://github.com/vme-im/vme-content/issues/78');
