INSERT INTO items VALUES ('I_kwDOLrzjj86fo9rl','我的嘴真笨','我的嘴真笨，总能把话题聊死了，跟你找话题好难，何况我这么喜欢你，连口嗨都要挑拣半天呢，其实每一句轻飘飘的爬，都是我难以启齿的心事。我最近越来越期待夜晚了，因为白天都没什么机会能和你说话，只能憋到晚上和你说句晚安。但你可别小看这两个字，它可包含着我今天清晨见到的阳光，中午看到的白云，傍晚遇见的微风，包含着我一天想对你说的话。说了这么多，你听得到吗，其实我在说今天是肯德基疯狂星期四，v我50，抚慰我支离破碎的心。如果你想让我开心点，v我100，我也吃得完','zkl2333',1732172958000,0,'text','f5eee72c526fcd70c66dbf761a7a1b2a45bc38ce8232aabd740ef0770fcdbd2b','https://github.com/vme-im/vme-content/issues/90');
