INSERT INTO items VALUES ('I_kwDOLrzjj86FXTiN','我本是夜上海的一名贫穷又自强的黄包车夫','我本是夜上海的一名贫穷又自强的黄包车夫，看遍了这个城市的繁华和热闹，也体验了这个社会的冷漠与无情。直到那一天，我的车上坐上了一位穿着四季歌的千金小姐，我感到了我平静已久的内心再一次颤动，我知道不应该，但我却还是爱上了。我知道我的身份地位配不上她，只求有个好心人给我39.9，让我买一个疯狂星期四热辣鸡桶，带给她舔狗的关怀。','zkl2333',1712834139000,0,'text','08b663e1785a434c7789a654ada87a70c158e27ef63cbdc3c5c711c471b726a2','https://github.com/vme-im/vme-content/issues/35');
INSERT INTO items VALUES ('I_kwDOLrzjj86FXTQn','后来不是报警了吗 那个男的隔了一个星期才找到','后来不是报警了吗 那个男的隔了一个星期才找到 把他的父母和我朋友的父母喊到警察局里商量这件事到底怎么办 要不就结婚把这个孩子生下来 要么就打掉并赔偿我朋友30w 男方不想要这个孩子但是父母手头也没有这多钱 硬着头皮跟我朋友结婚了 彩礼才拿了八万 结婚后男的经常不归家在外面玩 我朋友挺着大肚子在家真的不容易 然后我实在看不下去了 就去照顾我朋友 我准备拿起手机给他打电话 又不小心点开肯德基 才想起来今天是肯德基Fucking Crazy Thursday 疯狂星期四 谁请我吃我继续说','zkl2333',1712834098000,0,'text','a8d712f923b20efd214a021c3638f327f93a76206e48571e860e101728e9a916','https://github.com/vme-im/vme-content/issues/33');
INSERT INTO items VALUES ('I_kwDOLrzjj86FXTWr','男朋友跟我分手了','男朋友跟我分手了，我心碎了决定见她一面把事情说清楚如果她非要分手我也无话可说。到了她家门口，死活不出来。我只是一片凋零的落叶，随着风飘落，我时常在想我的凋零是我自己的选择，还是风不挽留，就像茫茫大海里的一条孤单的鱼没有人会关心我，没有人会想念我。如果有一天我被人类发现，也许是我的生命走到了尽头，人类是贪婪的，是有欲望的，鱼在他们眼里是无尽的财富海洋资源在他们眼里是赖以生存的摇钱树，有人捕鱼，有人抓蚌壳，蚌壳那么不容易，她用自己的血肉磨出了珍珠，一颗又一颗，说到珍珠，你愿不愿意转我十块钱买一杯珍珠奶茶给我这条小鱼，哎看来我是一条无人疼爱的小鱼，不过是一条无人关心无人疼爱无人喜欢无人给我买奶茶的可怜巴巴的小鱼。我心如死灰在大街上游荡，打开手机看到了我们的恩爱时光泪流满面，忽然注意到手机上显示的时间','zkl2333',1712834112000,0,'text','9c23cf62ad3843fa5bc34384a49c38f9bb1cfa4ef5ce702c55a112e928ef548d','https://github.com/vme-im/vme-content/issues/34');
