INSERT INTO items VALUES ('I_kwDOLrzjj86hBM73','小时候听老人常说','小时候听老人常说“冬吃汉堡夏吃姜，不用大夫开药方”，所有汉堡中双层芝士牛肉霸王堡最为正宗。我们的老祖宗认为冬季是个寒冷的季节，所以要在家里多吃汉堡为未来一年的生活打下好基础。这是我们的宝贵传统，一定要好好保护能不丢掉，现在很多年轻人已经不知道这层寓意了，真的是很悲哀。今天是肯德基疯狂星期四，现在v我50，让我们一起留下宝贵的传统文化。','zkl2333',1732785867000,0,'text','337425bcdb9c58493896cba6a89230e33aca8b7817043bd9ef317967e536e7b7','https://github.com/vme-im/vme-content/issues/93');
