INSERT INTO items VALUES ('I_kwDOLrzjj86iG4PN','我经常不敢相信自己已经快奔三了','讲真的，今年已经到十二月啦，我经常不敢相信自己已经快奔三了，身边的人都在往前走，恋爱，工作，谈婚论嫁，只有我好像还停留在十年前的时光里，喜怒哀乐仍然在我的脸上，时间让我长了年岁，却没有让我成为一个合格的大人。我以为我的21岁，会工作稳定，收入可观，和喜欢的人去看山河大海，落日余晖。没想到，到了谈婚论嫁的年龄，我却仍在找自己的路上。所以，今天肯德基疯狂星期四，谁请我吃?','zkl2333',1733386965000,0,'text','897137563a70eedc5a22d821a92487e2ca9d3b87704ea37fa969c05bdaa4f78b','https://github.com/vme-im/vme-content/issues/95');
