INSERT INTO items VALUES ('I_kwDOLrzjj86j2-O8','水滴筹','[水滴筹]很抱歉打扰大家，本人干2024年12月19日上午9点11分查出两眼昏花饥饿症，情况紧急
所幸有个朋友的姥爷是中医，让我照着这个药方抓药:
蛋挞*2、烤翅*3对、鸡块*2、薯条*2、可乐*500ml、原味鸡*2，谁v我50 去抓药
周期性蛋白脂肪缺乏症(学名 Insanus lovis)是一种广泛存在的慢性病，易感人群多为中国大陆年轻群体，目前暂无有效的治愈方法，只能通过使用美国公司Kentucky Fried Chicken (简称KFC)开发的生物制剂Fried Animal Protein(FAP,中文译名飞普)经由食道对胃与小肠中受体进行靶向治疗缓解症状。今天是该公司降低药物售价的日子，资助50帮我治疗该慢性病','haojingkexudu',1734574862000,1,'text','8e7457311f7eb947d3ca0ffdb55efc1cafaec0cff4d2d268f4a4ecac027914d9','https://github.com/vme-im/vme-content/issues/106');
