INSERT INTO items VALUES ('I_kwDOLrzjj86j3wp-','国王判刑','一个国王叫肯，纳了一个歌姬，歌姬不老实搞小动作，背着肯大搞矿产开发，为了实现矿产垄断，歌姬把其他同行的矿井都给封了，问定什么罪？大家觉得定什么罪？死罪。肯的姬封矿刑期死','haojingkexudu',1734586390000,1,'text','1bba217ab183e5c9c8ea72c6a3dae61205b50950ccc6cf108ed1f44c5ae00bf1','https://github.com/vme-im/vme-content/issues/107');
