INSERT INTO items VALUES ('I_kwDOLrzjj86JztVx','我不想你带着情绪过夜','我不想你带着情绪过夜，这样会把你推的越来越远，我不想你离开我，我希望你可以多爱我一点，我不想因为一点点小问题就让我们两之间的感情产生隔阂。对我来说，双向奔赴的感情相处才有意义，看不到希望的事情我没办法坚持太久，我不想浪费时间在一些无意义无结果的事情上，时间应该用来做我该做的事情。很多人走不到最后，是因为理解不同步，但我跟你在一起，我知道你什样的人，我了解你甚至比了解自己还多，我和你在一起，不是因为其他，而是因为今天肯德基疯狂星期四，我希望你能请我吃！','zkl2333',1716444424000,0,'text','f23b4514721755fa4115b0eece0db557bf6721750b601b47b4b20c1a900fc046','https://github.com/vme-im/vme-content/issues/42');
