INSERT INTO items VALUES ('I_kwDOLrzjj86LUihS','明天高考了','明天高考了，这是我给高三考生的一点建议:
1.今天考完一定不要去对答案，尽情享受假期。
2.天气炎热的话注意避暑，可自带风油精、冰袋降温。
3.疯狂暗示自己，一定可以考出理想的成绩。
4.狂欢聚餐活动什么的，考后再计划也来得及。
5.星星之火，可以燎原，相信你我皆是黑马。
6.期待不要太高，不要眼高手低，做好困难准备。
7.四点那会考数学特别容易饿，中午一定要吃饱。
8.微博里经常有人发所谓标准答案，不要轻信。
9.我不会的题别人也不会，不要慌张。
10.五点考完可以去散散步放松心情，不要着急回家吃饭
11.十点半是最合适的上床时间。
最后给大家分享一首藏头诗，祝大家金榜题名。','zkl2333',1717655323000,0,'text','c11354a219ae2924f34a930bd8cae010b6e26bd0d08befbc5b43210ab3697d79','https://github.com/vme-im/vme-content/issues/46');
