INSERT INTO items VALUES ('I_kwDOLrzjj86PMiU1','分手','还是分手了 ，谢谢大家。
今天是7月11日，我们最终和平分手，其实从朋友到恋人我们发生了挺多事情，能走到一起也是很不容易。我喜欢你，很喜欢你，也想和你幼稚。对啊，我总问我自己为什么还能坚持，可能没有答案，我没有备胎，也不玩暧昧，我所有的脾气爱笑爱哭都给了你，我能为你做的最后一件事竟然是走出你的人生。我一点都不后悔，更谢谢你教会我成长。  我也不知道这是谁写的，挺感动的我就复制下来了，看到这里说明你很在乎我，天气很热能请我喝冰可乐吗，如果可以我想吃两瓶。如果不可以，今天肯德基疯狂星期四，我想吃八个蛋挞和原味鸡，谢谢。','zkl2333',1720681611000,1,'text','732f73867e4a56d70b5c9b651783d305c413ada0d92b9650da12a3421998b4b6','https://github.com/vme-im/vme-content/issues/52');
