INSERT INTO items VALUES ('I_kwDOLrzjj86qx4lc','我其实挺悲惨的','我其实挺悲惨的，我很小的时候就出生了，刚出生的两年里我甚至无法走路，每天只有靠趴才能去自己想去的地方，我走路时甚至无法睡觉！睡着了还经常兜不住屎！就这样我依然顽强的活着，V我52继续倾听我自强不息、逆天改命的故事','zkl2333',1740032818000,0,'text','f441a0db7679fba7cf592b41b6c1217c58b97688827f0d4ab54d5f0ab03c9f12','https://github.com/vme-im/vme-content/issues/124');
