INSERT INTO items VALUES ('I_kwDOLrzjj86qxuuO','你到底把我当什么？','你到底把我当什么？咱俩分手以后我真感觉自己活不下去了，为什么我把你想要都给你了，你还是走了。为你我把身体里的自己都掏空了，可是到最后我才发现，我对你所付出的感情在你眼里看来根本一文不值。因为你我跟自己父母吵的不可开交，跟我最好的几个朋友闹的反目成仇，我身边一个人都没有了，我只有你啊，可你为什么还要狠心抛弃我。我到底做错了什么你告诉我，究竟是杀了人还是放了火你要这样躲着我。一声不吭就离开了，你想过我吗，我记得你以前不是这样的，后来，你见的多了看的多了，酒你也会喝了，你好的坏的都见过了，也不听我说了，我一直活在你前女友的影子下，我知道你忘不了她，我也知道你一直在等她，可是我想不通，凭什么他尽情开心疯狂耍你你却让我哭泣，我说过让你跟我走让你抓紧我的双手，可你却连我这贱命瞅一下都不瞅，我生来对你亏欠，我活该自愿犯贱，就像那句话说的，人一旦有了感请，就窝囊的不行。我在你面前真的是没有一点尊严可言，永远卑微的像条狗。你跟我玩失联电话不接消息不回，我苦苦等你四十多天，我以为你会回来的。直到我听别人说你去找他复合了我才明白，原来从一开始你就没爱过我，可我不死心也不甘心。你就仗着我喜欢你才对我一伤到底，你爱的是你自己我却爱你到骨子里，真的，我从来都不敢发脾气，可你对我不留余地，好像只有我不舍得，你从来没珍惜过我，你根本就不爱我为什么要来招惹我？是你说过的要保护我，可后来的大风大雨都是你给的，我现在一个人活的猪狗不如。我没脸回去找他们，找我爸妈还有朋友。我伤透他们心了。这家也没了，事业没了，我不知道哭了多少回了，爱情没了，你也没了，我也太倒霉了。我不知道我还能怎么办，我不敢死也不敢活，打这么多字我也知道你不会看完，就想问一下你今天能不能v我50，我想吃肯德基了……','zkl2333',1740031227000,0,'text','57a082d9b1c674ce2ca7a5a9c0d5ca0bdcb13aefc67601708f371acad4e4fa69','https://github.com/vme-im/vme-content/issues/122');
