INSERT INTO items VALUES ('I_kwDOLrzjj87xylEh','假罚单','9月15日我的车被朋友开玩笑贴了一张假罚单，拍照发给我了，我当真了，就给男朋友打电话问他收到短信没她回答没收到，我以为是延迟了，所以登录12123查看，发现他的有几个违章，其中9.13，主副驾都没系安全带，副驾驶的女人，我不认识，看了一下违章地址，回忆了9.13他的行程，发现他9.13说谎了，就觉得不对劲了，心慌的很，下车路边站了一会才喘过气。稳定好情绪，计划等他晚上睡着查手机，他不知道我一直都知道他手机密码，凌晨3点，先打开微信并没有可疑的聊天记录，打开中国移动查了9.13当天的通话详单（他有个习惯，就是啥事都打电话，不爱发微信，我猜想她去接人家肯定要打电话联系)发现几个可疑号码，微信逐个添加好友，就马上出现了怀疑对象，好家伙，居然没删微信，只是删除聊天记录，心真大啊，查看往来账款，一年半来转账66661999 1888 2000666999等大概16000元这样，没有聊天记录也大概明白了绝不是普通关系。电话号码储存还备注了名字，他是真敢啊，打开他抖音查看点赞对象最多的就是那个，我怀疑是三，看到抖音评论知道了三的姓氏，支付宝输入手机号，选择转账，姓氏对上了，确定了抖音那个人是三。通过抖音视频知道了三的家庭情况，20岁左右工作地点父母兄弟等，三的抖音我全部录屏，以防败露之后他隐藏起来。查了半年的通话详单，知道每月都要打30通左右电话，平均15分钟以上，全部拍照保存，下载他微信的年账单，发我邮箱了，因为年账单是删不掉任何记录的，我要一笔笔对他的账单。手机能查的能拍的都保存了，手机也被我扣起来了，一顿操作两个小时再爆发。反正也睡不着，就打开年账单看了9.13消费记录和他的手机进行比对，果然，女装女鞋吃饭一条龙。记录显示违章的时间地点对上了。再继续翻，临时房消费记录和几次邻市买男装，吃饭的消费记录也找到了。越翻心越痛回来时他在吃早餐，我说别吃了，你和她什么时候开始的，他以为我没有证据，我说你全部说实话，懂的都懂。死不承讣，证据都摆到面前时，愣了，然后开始忏悔。我懒得听，第一件事，算账单，把钱要回来我直接用她手机给三打电话:她给你花的钱，我一会算好，发给你，12点之前转过来。三说：好，今天疯狂星期四，v我50','zkl2333',1773215976000,0,'text','b20df68a7bde540f2b77b0c4aa779b77a6727d7cd36ab3ba43f15d2688125203','https://github.com/vme-im/vme-content/issues/184');
